      const quality = el("select", {"aria-label": "Quality for these videos", onchange: (event) => { b.preset = event.target.value; }},
        QUALITY_CHOICES.filter((value) => value !== "ask").map((value) => el("option", {value, text: QUALITY_LABELS[value], selected: b.preset === value})));
      const section = el("div", {class: "section"}, [
        el("p", {class: "note", text: "Click thumbnails on the page to add or remove them."}),
        el("div", {class: "row"}, [
          el("button", {class: "btn btn-ghost", type: "button", text: "Select all on this page (" + selectable.length + ")", disabled: !selectable.length, onclick: () => { for (const entry of selectable) b.picked.add(entry.url); refreshPicks(); render(); renderDock(); }}),
          b.picked.size ? el("button", {class: "btn btn-ghost", type: "button", text: "Clear", onclick: () => { b.picked.clear(); refreshPicks(); render(); renderDock(); }}) : null,
        ]),
      ]);
      if (settings.marks) {
        const skip = el("input", {type: "checkbox", checked: b.skipSaved, onchange: (event) => { b.skipSaved = event.target.checked; refreshPicks(); render(); }});
        section.append(el("label", {class: "setting check", style: "margin:12px 0 0"}, [skip, "Skip videos I downloaded before" + (skipped ? " (" + skipped + ")" : "")]));
      }
      section.append(el("label", {class: "setting", style: "margin:12px 0 0"}, ["Quality for these videos", quality]));
      section.append(el("p", {class: "count", text: b.picked.size + " selected" + (cfg.left !== null ? " · " + cfg.left + " downloads left today" : "")}));
      if (plan.over > 0) {
        const byDay = cfg.left !== null && cfg.left < cfg.maxItems;
        section.append(el("p", {class: "note", text: "Only the first " + plan.take.length + " go in this batch: " + (byDay ? "that's what is left of today's downloads." : "a batch holds up to " + cfg.maxItems + " videos.")}));
      }
      if (!supporterActive()) {
        section.append(el("p", {class: "note"}, [
          "Free: " + cfg.maxItems + " videos per batch, one at a time. A ",
          externalLink(NSFWDL + "/supporter?from=userscript-bulk", "Supporter key"), " (from $3) queues up to 100, 3 at a time, and 300 a day.",
        ]));
      }
      section.append(el("div", {class: "row"}, [el("button", {
        class: "btn btn-primary", type: "button", disabled: !plan.take.length,
        text: plan.take.length ? "⬇ Download " + plan.take.length + " video" + (plan.take.length === 1 ? "" : "s") : "⬇ Download",
        onclick: () => { if (plan.take.length) startBulk(plan.take); },
      })]));
      section.append(el("p", {class: "note", text: "Your browser may ask once to allow several downloads from this site: choose Allow. Keep this tab open while the batch runs."}));
      body.append(section);
    }
    return [header("Select videos", site.name + " · bulk download"), body, footer()];
  }

  // ── Buttons on thumbnails and the player (desktop, hover only) ─────────
  // One floating button, moved over whichever thumbnail the pointer is on,
  // or over the page's own player. Nothing is requested until it is clicked.
  const thumbHost = el("div", {id: THUMB_ID});
  for (const [prop, value] of [["position", "fixed"], ["display", "none"], ["z-index", "2147483646"]]) {
    thumbHost.style.setProperty(prop, value, "important");
  }
  const thumbShadow = thumbHost.attachShadow({mode: "open"});
  const thumbButton = el("button", {type: "button", text: "⬇ NSFWDL", title: "Download this video with NSFWDL"});
  thumbShadow.append(el("style", {text: THUMB_STYLE}), thumbButton);
  let thumbTarget = null;
  let thumbIsPage = false;
  let thumbHideTimer = 0;
  let playerCache = {at: 0, rect: null};

  function hideThumb() {
    thumbHost.style.setProperty("display", "none", "important");
    thumbTarget = null;
  }

  // The single-video URL of the link under the pointer, thumbnail or not.
  function linkUrlFor(node) {
    const anchor = node && node.closest ? node.closest("a[href]") : null;
    if (!anchor || host.contains(anchor)) return null;
    return videoLinkTarget(site, anchor.getAttribute("href"), location.href);
  }

  function thumbnailFor(node) {
    const anchor = node && node.closest ? node.closest("a[href]") : null;
    if (!anchor || host.contains(anchor)) return null;
    // The biggest image in the link: sites put small icons, badges or a
    // hidden lazy-loading copy next to the real thumbnail.
    let rect = null;
    for (const media of anchor.querySelectorAll("img, video, picture")) {
      const box = media.getBoundingClientRect();
      if (!rect || box.width * box.height > rect.width * rect.height) rect = box;
    }
    if (!rect || rect.width < 120 || rect.height < 68) return null;
    const url = videoLinkTarget(site, anchor.getAttribute("href"), location.href);
    if (!url || url === state.pageUrl) return null;
    return {url, rect};
  }

  // The page's own player: the biggest visible video, or a known player box
  // before the video element has loaded. Looked up at most every 800 ms.
  const PLAYER_SELECTORS = "video, #player, #xplayer, #video-player, .mgp_container, .video-player, .player-container, .xp-player";
  function playerRect() {
    if (Date.now() - playerCache.at < 800) return playerCache.rect;
    let best = null;
    for (const node of document.querySelectorAll(PLAYER_SELECTORS)) {
      if (host.contains(node)) continue;
      const box = node.getBoundingClientRect();
      if (box.width < 320 || box.height < 180 || box.bottom <= 0 || box.top >= window.innerHeight) continue;
      if (!best || box.width * box.height > best.width * best.height) best = box;
    }
    playerCache = {at: Date.now(), rect: best};
    return best;
  }

  function playerFor(event) {
    if (!state.pageUrl) return null;
    const rect = playerRect();
    if (!rect || event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) return null;
    return {url: state.pageUrl, rect, page: true};
  }

  const canHover = window.matchMedia && window.matchMedia("(hover: hover) and (pointer: fine)").matches;
  if (inPage && canHover) {
    document.addEventListener("mouseover", (event) => {
      if (!settings.thumbs || state.bulk.selecting) return;
      if (event.target === thumbHost) { clearTimeout(thumbHideTimer); return; }
      const found = thumbnailFor(event.target) || playerFor(event);
      if (!found) {
        // XVideos and XNXX lay a second link to the same video over the
        // thumbnail; moving onto it must not hide the button.
        if (thumbTarget && linkUrlFor(event.target) === thumbTarget) clearTimeout(thumbHideTimer);
        return;
      }
      clearTimeout(thumbHideTimer);
      thumbTarget = found.url;
      thumbIsPage = Boolean(found.page);
      const again = wasDownloaded(found.url);
      thumbButton.textContent = found.page ? (again ? "✓ Again" : "⬇ Download") + " · NSFWDL" : again ? "✓ Again · NSFWDL" : "⬇ NSFWDL";
      thumbHost.style.setProperty("top", Math.max(4, found.rect.top + 8) + "px", "important");
      thumbHost.style.setProperty("left", Math.max(4, found.rect.left + 8) + "px", "important");
      thumbHost.style.setProperty("display", "block", "important");
      if (!thumbHost.isConnected) document.body.appendChild(thumbHost);
    }, true);
    document.addEventListener("mouseout", (event) => {
      if (!thumbTarget) return;
      const to = event.relatedTarget;
      if (to === thumbHost || (to && linkUrlFor(to) === thumbTarget)) return;
      clearTimeout(thumbHideTimer);
      thumbHideTimer = setTimeout(hideThumb, 250);
    }, true);
    window.addEventListener("scroll", hideThumb, {passive: true, capture: true});
    thumbButton.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const url = thumbTarget;
      const isPage = thumbIsPage;
      hideThumb();
      if (!url) return;
      ensureWidget();
      if (isPage) dockAction();
      else openPanelFor(url, {oneClick: true});
    });
  }

  // ── Downloaded marks on thumbnails ─────────────────────────────────────
  // A green outline on the thumbnail of a video saved before: an attribute
  // and one style rule, so the site's layout is never changed.
  const MARK_STYLE_ID = "nsfwdl-marks-style";
  let marksTimer = 0;
  let marksObserver = null;
  let marksLastRun = 0;
  // Links already looked at (and their href then), so a busy page that
  // keeps changing its DOM costs only the new links.
  let marksSeen = new WeakMap();

  function scheduleMarks() {
    if (marksTimer) return;
    marksTimer = setTimeout(() => { marksTimer = 0; marksLastRun = Date.now(); applyMarks(); }, Math.max(400, 1500 - (Date.now() - marksLastRun)));
  }

  function biggestMedia(anchor) {
    let best = null;
    let area = 0;
    for (const media of anchor.querySelectorAll("img, video, picture")) {
      const box = media.getBoundingClientRect();
      if (box.width * box.height > area) { best = media; area = box.width * box.height; }
    }
    return area >= 120 * 68 ? best : null;
  }

  function applyMarks() {
    const enabled = settings.marks && Object.keys(history).length > 0;
    if (!enabled) {
      for (const node of document.querySelectorAll("[data-nsfwdl-saved]")) node.removeAttribute("data-nsfwdl-saved");
      return;
    }
    if (!document.getElementById(MARK_STYLE_ID) && document.head) {
      document.head.append(el("style", {id: MARK_STYLE_ID, text: "[data-nsfwdl-saved]{outline:3px solid #22c55e !important;outline-offset:-3px !important}"}));
    }
    for (const anchor of document.querySelectorAll("a[href]")) {
      const href = anchor.getAttribute("href");
      if (marksSeen.get(anchor) === href || host.contains(anchor)) continue;
      const url = videoLinkTarget(site, href, location.href);
      // Thumbnails that haven't laid out yet are looked at again later.
      if (!url || !wasDownloaded(url)) { marksSeen.set(anchor, href); continue; }
      if (!url || !wasDownloaded(url)) continue;
      const media = biggestMedia(anchor);
      if (media) marksSeen.set(anchor, href);
      if (media && !media.hasAttribute("data-nsfwdl-saved")) {
        media.setAttribute("data-nsfwdl-saved", "");
        if (!media.getAttribute("title")) media.setAttribute("title", "Downloaded before with NSFWDL");
      }
    }
    if (!marksObserver && typeof MutationObserver === "function" && document.body) {
      // Listings load more thumbnails as you scroll, and carousels reveal
      // thumbnails that were hidden (0x0) at the first look.
      marksObserver = new MutationObserver(scheduleMarks);
      marksObserver.observe(document.body, {childList: true, subtree: true});
      window.addEventListener("scroll", scheduleMarks, {passive: true});
    }
  }

  // ── Keyboard shortcut and menu ─────────────────────────────────────────
  document.addEventListener("keydown", (event) => {
    if (event.altKey && event.shiftKey && !event.ctrlKey && !event.metaKey && (event.key === "D" || event.key === "d" || event.code === "KeyD")) {
      if (!host.isConnected || !inPage) return;
      event.preventDefault();
      if (state.collapsed) { state.collapsed = false; writeValue("collapsed", false); renderDock(); }
      if (state.open) closePanel(); else dockAction();
    }
  }, true);
  shadow.addEventListener("keydown", (event) => { if (event.key === "Escape" && state.open) closePanel(); });

  try {
    if (typeof GM_registerMenuCommand === "function") {
      GM_registerMenuCommand("NSFWDL settings", () => {
        ensureWidget();
        state.collapsed = false;
        writeValue("collapsed", false);
        state.view = "settings";
        openPanel();
      });
    }
  } catch (_) { /* optional */ }

  // ── Page tracking ──────────────────────────────────────────────────────
  // The dock shows on single-video pages and while a RedGifs feed has a
  // video on screen, and also elsewhere while it has
  // downloads to show (a thumbnail started one, or the site changed pages
  // without reloading).
  function ensureWidget() {
    if (!host.isConnected && document.body) document.body.appendChild(host);
  }

  let lastHref = "";
  let lastVideo = null;
  let lastListing = false;
  function sync() {
    const video = currentVideoUrl(site, location.href, document);
    const listing = checkListing();
    if (location.href === lastHref && video === lastVideo && listing === lastListing) return;
    // The site moved to another page without reloading: the picks were for the old one.
    if (lastHref && location.href !== lastHref && state.bulk.selecting) stopSelecting(true);
    lastHref = location.href;
    lastVideo = video;
    lastListing = listing;
    const onVideo = Boolean(video);
    state.pageUrl = video;
    if (onVideo || listing || state.jobs.length || state.open) {
      ensureWidget();
      renderDock();
      if (state.open && state.view === "pick" && onVideo && state.target && state.target.url !== state.pageUrl && !state.target.loading) render();
    } else if (host.isConnected) {
      closePanel();
      host.remove();
    }
  }
  renderDock();
  sync();
  // The SPA sync runs slower while the tab is hidden and catches up as soon
  // as it is visible again. try/finally: one throwing sync() must never stop
  // the chain.
  let syncTimer = 0;
  function scheduleSync() {
    clearTimeout(syncTimer);
    syncTimer = setTimeout(() => { try { sync(); } finally { scheduleSync(); } }, syncDelay());
  }
  scheduleSync();
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) return;
    try { sync(); } finally { scheduleSync(); }
    if (supporterToken()) refreshSupporterEntitlement();
  });
  // Back from nsfwdl.com (say, after buying a key there): unlock an open
  // panel without a reload when the site now has a key for this browser.
  document.addEventListener("visibilitychange", () => {
    if (document.hidden || supporterToken()) return;
    siteLinkAt = 0;
    if (!state.open) return;
    linkFromSite().then((linked) => {
      if (!linked) return;
      resetTargetLocks();
      if (state.bulk.config) state.bulk.configAt = 0;
      render();
    });
  });
  scheduleMarks();
})();

