  function removeJob(job) {
    state.jobs = state.jobs.filter((item) => item !== job);
  }

  function updateJob(job, changes) {
    const before = job.phase;
    Object.assign(job, changes);
    if (changes.phase === "saved" && !job.counted) {
      job.counted = true;
      writeValue("savedCount", (Number(readValue("savedCount", 0)) || 0) + 1);
    }
    if (changes.phase && changes.phase !== before) {
      // A batch notifies once when it pauses or ends, not for every video.
      if (changes.phase === "saved" || changes.phase === "handed") {
        rememberDownload(job.target && job.target.url);
        renderDock();
        if (!job.bulk) notify((changes.phase === "saved" ? "Saved: " : "Handed to your browser: ") + job.title);
      } else if (changes.phase === "stalled") {
        if (job.bulk) {
          // The browser held the file back (Chrome asks once per site before
          // several downloads): stop, or NSFWDL would prepare files nobody gets.
          pauseBulk("stalled", "Your browser held a file back instead of saving it. Allow multiple downloads for this site (the icon at the right of the address bar), and the batch continues.");
        } else {
          notify("Your file is ready. Come back to the tab to save it: " + job.title);
        }
      } else if (changes.phase === "failed") {
        if (!job.bulk) notify("Download failed: " + job.title);
      }
      if (job.bulk) bulkProgress(job, changes.phase);
      // A slot may have freed up.
      if (!RUNNING.includes(changes.phase)) pump();
    }
    render();
  }

  // Starts waiting jobs, oldest first, while fewer than the limit run.
  let pumpTimer = 0;
  function pump() {
    clearTimeout(pumpTimer);
    const limit = supporterActive() ? MAX_PARALLEL : FREE_PARALLEL;
    let running = state.jobs.filter((job) => RUNNING.includes(job.phase)).length;
    let runningBulk = state.jobs.filter((job) => job.bulk && RUNNING.includes(job.phase)).length;
    let nextWake = 0;
    const wakeAt = (at) => { nextWake = nextWake ? Math.min(nextWake, at) : at; };
    // Normal clicks first, then the bulk batch in what room is left.
    for (const job of state.jobs) {
      if (job.bulk || job.phase !== "waiting") continue;
      if (job.notBefore && job.notBefore > Date.now()) { wakeAt(job.notBefore); continue; }
      if (running >= limit) break;
      running += 1;
      runJob(job);
    }
    const b = state.bulk;
    const parallel = b.config ? b.config.parallel : 0;
    const gapMs = b.config ? b.config.gapMs : 2000;
    const held = b.holdUntil > Date.now();
    if (held && state.jobs.some((job) => job.bulk && job.phase === "waiting")) wakeAt(b.holdUntil);
    for (const job of state.jobs) {
      if (held || !job.bulk || job.phase !== "waiting" || b.paused) continue;
      if (job.notBefore && job.notBefore > Date.now()) { wakeAt(job.notBefore); continue; }
      const now = Date.now();
      if (!bulkMayStart({paused: b.paused, parallel, runningBulk, running, limit, now, lastStart: b.lastStart, gapMs})) {
        if (now - b.lastStart < gapMs && runningBulk < parallel && running < limit - 1) wakeAt(b.lastStart + gapMs);
        break;
      }
      running += 1;
      runningBulk += 1;
      b.lastStart = now;
      runJob(job);
    }
    let ahead = 0;
    for (const job of state.jobs) if (job.phase === "waiting" && !job.bulk) job.ahead = ahead++;
    if (nextWake) pumpTimer = setTimeout(pump, Math.max(500, nextWake - Date.now()));
  }

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  function startJob(choice, forTarget) {
    const target = forTarget || state.target;
    if (choice.overPlanLimit || choice.sizeRefused) {
      if (target) target.sizeRefusal = choice;
      render();
      return;
    }
    const url = target && target.url;
    // A repeated click on the same quality of the same video.
    if (state.jobs.some((job) => job.choice?.ref === choice.ref && job.target && job.target.url === url && !FINISHED.includes(job.phase))) {
      if (!state.open) { state.open = true; renderDock(); }
      render();
      return;
    }
    const title = (target && target.info && target.info.title) || site.name + " video";
    const job = {
      choice, target, title, label: choice.label, sizeBytes: choice.sizeBytes, sizeExact: choice.sizeExact,
      phase: "waiting", ahead: 0, attempts: 0, slotWaitSince: 0, notBefore: 0, bytesPrepared: 0, fileUrl: null, error: "", retry: false, supporter: false,
    };
    state.jobs.push(job);
    const single = state.jobs.filter((item) => !item.bulk);
    if (single.length > 12) {
      const keep = new Set(single.slice(-12));
      state.jobs = state.jobs.filter((item) => item.bulk || keep.has(item) || activeJobs().includes(item));
    }
    if (!state.open) { state.open = true; renderDock(); }
    pump();
    render();
  }

  // NSFWDL refused the file because this connection already reads its limit
  // of files at once: put the job back in line until a slot frees (see
  // SLOT_WAIT_MS).
  function requeue(job, seconds) {
    const now = Date.now();
    if (!job.slotWaitSince) job.slotWaitSince = now;
    if (now - job.slotWaitSince > SLOT_WAIT_MS) return false;
    job.attempts += 1;
    updateJob(job, {phase: "waiting", notBefore: now + slotRetrySeconds(job.attempts, seconds) * 1000, id: null, fileUrl: null, bytesPrepared: 0});
    return true;
  }

  // A bulk video has no format yet: list its formats like the panel does
  // and take the batch's quality preset.
  async function resolveBulkChoice(job) {
    await checkSupporter();
    const url = job.target.url;
    const route = await api("POST", "/api/route", {url, page_path: BULK_PAGE_PATH}, 20000);
    const payload = {url, mode: route.mode || "validated", device: deviceClass(), page_path: BULK_PAGE_PATH};
    if (route.source) payload.expected_source = route.source;
    const data = await api("POST", "/api/extract", payload, 60000);
    await siteLinkSettled();
    const choices = normalizeFormats(data, supporterActive(), supporterLimitBytes);
    job.target.choices = choices;
    job.target.info = data;
    const choice = pickPreferred(choices, state.bulk.preset);
    if (!choice) throw Object.assign(new Error("No downloadable format was found for this video."), {transient: false});
    const title = typeof data.title === "string" && data.title.trim() ? data.title.trim().slice(0, 200) : job.title;
    Object.assign(job, {choice, choiceAt: Date.now(), title, label: choice.label, sizeBytes: choice.sizeBytes, sizeExact: choice.sizeExact});
  }

  async function runJob(job) {
    job.phase = "starting";   // holds its slot from this moment
    job.notBefore = 0;
    job.busyWait = false;
    render();
    try {
      if (job.bulk && job.choice && Date.now() - (job.choiceAt || 0) > BULK_REF_MAX_AGE_MS) job.choice = null;
      if (!job.choice) await resolveBulkChoice(job);
      const started = await api("POST", "/api/download", {format_ref: job.choice.ref, page_path: job.bulk ? BULK_PAGE_PATH : PAGE_PATH}, 30000);
      const fileUrl = safeDownloadUrl(started.download_url);
      const id = /^[A-Za-z0-9_-]{20,128}$/.test(String(started.download_id || "")) ? started.download_id : null;
      if (!fileUrl || !id) throw Object.assign(new Error("NSFWDL returned an unexpected answer. Try again."), {transient: true});
      state.dailyLeft = Number.isInteger(started.free_downloads_left_today) ? started.free_downloads_left_today : null;
      if (state.jobs.some((other) => other !== job && other.id === id && activeJobs().includes(other))) {
        removeJob(job);   // the same download is already running (a repeated click)
        pump();
        render();
        return;
      }
      updateJob(job, {id, fileUrl, phase: started.state === "ready" ? "saving" : started.state === "queued" ? "queued" : "preparing"});
      if (started.state !== "ready") await waitUntilReady(job);
      updateJob(job, {phase: "saving"});
      saveFile(fileUrl);
      await followHandoff(job);
    } catch (error) {
      if (error && error.kind === "rate_limited_active_downloads" && requeue(job, error.retryAfter)) return;
      if (job.bulk && error) {
        // The site or NSFWDL is busy: wait and try again, it is not a failure.
        if (BULK_WAIT_KINDS.includes(error.kind)) {
          job.busyWait = true;
          if (requeue(job, error.retryAfter)) {
            // The rest of the batch waits too, instead of each asking again.
            state.bulk.holdUntil = Math.max(state.bulk.holdUntil, job.notBefore);
            pump();
            return;
          }
          job.busyWait = false;
        }
        // expired_format_ref: the format list is stale. free_hd_allowance_used:
        // today's free 1080p ran out after this video's list was read, so a
        // fresh list offers the best free quality (720p or lower) instead.
        if ((error.kind === "expired_format_ref" || error.kind === "free_hd_allowance_used") && !job.refRetried) {
          job.refRetried = true;
          job.choice = null;
          if (requeue(job, 1)) return;
        }
        if (error.kind === "rate_limited_daily_downloads") pauseBulk("daily", "Today's downloads are used up, so the rest of this batch can't start today.");
      }
      const sizeFailure = ["file_too_large_supporter", "file_exceeded_supporter_safety_ceiling"].includes(error && error.kind);
      const sizeAlternative = sizeFailure && job.target ? bestFittingFormat(job.target.choices, job.choice) : null;
      if (sizeFailure && job.choice) {
        job.choice.sizeRefused = true;
        if (job.target) job.target.sizeRefusal = job.choice;
      }
      updateJob(job, {
        phase: "failed",
        error: sizeFailure ? failureMessage(error.kind) : (error && error.message) || "This download failed.",
        errorKind: error && error.kind,
        retry: Boolean(error && error.transient),
        supporter: Boolean(error && error.supporter),
        supporterFrom: error && error.kind === "rate_limited_daily_downloads" ? "userscript-cap" : "userscript-size",
        sizeAlternative,
      });
      if (!state.open && !job.bulk) { state.open = true; renderDock(); render(); }
    }
  }

  async function poll(job) {
    let misses = 0;
    for (;;) {
      try {
        return await api("GET", "/api/download/" + encodeURIComponent(job.id) + "/status", null, 20000);
      } catch (error) {
        // A dropped poll is not a failed job; the server keeps working.
        if (!error.transient || ++misses >= 5) throw error;
        await sleep(1000 * misses);
      }
    }
  }

  async function waitUntilReady(job) {
    const deadline = Date.now() + PREPARE_DEADLINE_MS;
    while (Date.now() < deadline) {
      await sleep(pollDelay());
      const status = await poll(job);
      if (status.state === "ready") return;
      if (status.state === "failed") {
        throw Object.assign(new Error(failureMessage(status.error_kind)), {kind: status.error_kind, transient: !["file_too_large_free", "file_exceeded_free_safety_ceiling", "file_too_large_supporter", "file_exceeded_supporter_safety_ceiling", "geo_blocked", "media_unavailable", "paid_content"].includes(status.error_kind), supporter: /^file_(too_large|exceeded)_free/.test(String(status.error_kind || ""))});
      }
      updateJob(job, {phase: status.state === "queued" ? "queued" : "preparing", bytesPrepared: Number(status.bytes_prepared) || 0});
    }
    throw Object.assign(new Error("Preparing this file took too long. Try again or open it on NSFWDL."), {transient: true});
  }

  function failureMessage(kind) {
    const messages = {
      file_too_large_free: "This file is over the 500 MB free limit. Choose a smaller quality.",
      file_exceeded_free_safety_ceiling: "This file turned out larger than the free allowance. Choose a smaller quality.",
      file_too_large_supporter: `This file exceeds your Supporter plan size limit (${formatCapText()}). Choose a smaller quality.`,
      file_exceeded_supporter_safety_ceiling: `This file exceeded your Supporter plan size limit (${formatCapText()}). Choose a smaller quality.`,
      geo_blocked: "The site blocks this video in the country NSFWDL's server is in.",
      media_unavailable: "This video is unavailable, private, or removed.",
      upstream_download_failed: "The site couldn't deliver this file. Try again or choose another quality.",
      preparation_timeout: "Preparing this file took too long. Try another quality.",
      merge_failed: "The video and audio couldn't be combined. Try another quality.",
      media_url_expired: "The video link expired. Try again.",
