    b.links = pageVideoLinks(true);
    const live = new Set();
    for (const entry of b.links) {
      live.add(entry.media);
      entry.skip = b.skipSaved && wasDownloaded(entry.url);
      if (entry.skip) b.picked.delete(entry.url);
