      section.append(el("p", {class: "note", text: "Your browser may ask once to allow several downloads from this site: choose Allow. Keep this tab open while the batch runs."}));
      body.append(section);
    }
    return [header("Select videos", site.name + " · bulk download"), body, footer()];
  }

  // ── Buttons on thumbnails and the player (desktop, hover only) ─────────
  // One floating button, moved over whichever thumbnail the pointer is on,
  // or over the page's own player. Nothing is requested until it is clicked.
  const thumbHost = el("div", {id: THUMB_ID});
  for (const [prop, value] of [["position", "fixed"], ["display", "none"], ["z-index", "2147483646"]]) {
    thumbHost.style.setProperty(prop, value, "important");
  }
  const thumbShadow = thumbHost.attachShadow({mode: "open"});
  const thumbButton = el("button", {type: "button", text: "⬇ NSFWDL", title: "Download this video with NSFWDL"});
  thumbShadow.append(el("style", {text: THUMB_STYLE}), thumbButton);
  let thumbTarget = null;
  let thumbIsPage = false;
  let thumbHideTimer = 0;
  let playerCache = {at: 0, rect: null};

  function hideThumb() {
    thumbHost.style.setProperty("display", "none", "important");
    thumbTarget = null;
  }

  // The single-video URL of the link under the pointer, thumbnail or not.
  function linkUrlFor(node) {
    const anchor = node && node.closest ? node.closest("a[href]") : null;
    if (!anchor || host.contains(anchor)) return null;
    return videoLinkTarget(site, anchor.getAttribute("href"), location.href);
  }

  function thumbnailFor(node) {
    const anchor = node && node.closest ? node.closest("a[href]") : null;
    if (!anchor || host.contains(anchor)) return null;
    // The biggest image in the link: sites put small icons, badges or a
    // hidden lazy-loading copy next to the real thumbnail.
    let rect = null;
    for (const media of anchor.querySelectorAll("img, video, picture")) {
      const box = media.getBoundingClientRect();
      if (!rect || box.width * box.height > rect.width * rect.height) rect = box;
    }
    if (!rect || rect.width < 120 || rect.height < 68) return null;
    const url = videoLinkTarget(site, anchor.getAttribute("href"), location.href);
    if (!url || url === state.pageUrl) return null;
    return {url, rect};
