    }
    for (const anchor of document.querySelectorAll("a[href]")) {
      const href = anchor.getAttribute("href");
      if (marksSeen.get(anchor) === href || host.contains(anchor)) continue;
      const url = videoLinkTarget(site, href, location.href);
      // Thumbnails that haven't laid out yet are looked at again later.
      if (!url || !wasDownloaded(url)) { marksSeen.set(anchor, href); continue; }
      if (!url || !wasDownloaded(url)) continue;
      const media = biggestMedia(anchor);
      if (media) marksSeen.set(anchor, href);
      if (media && !media.hasAttribute("data-nsfwdl-saved")) {
        media.setAttribute("data-nsfwdl-saved", "");
        if (!media.getAttribute("title")) media.setAttribute("title", "Downloaded before with NSFWDL");
      }
    }
    if (!marksObserver && typeof MutationObserver === "function" && document.body) {
      // Listings load more thumbnails as you scroll, and carousels reveal
      // thumbnails that were hidden (0x0) at the first look.
      marksObserver = new MutationObserver(scheduleMarks);
      marksObserver.observe(document.body, {childList: true, subtree: true});
      window.addEventListener("scroll", scheduleMarks, {passive: true});
    }
  }

  // ── Keyboard shortcut and menu ─────────────────────────────────────────
  document.addEventListener("keydown", (event) => {
    if (event.altKey && event.shiftKey && !event.ctrlKey && !event.metaKey && (event.key === "D" || event.key === "d" || event.code === "KeyD")) {
      if (!host.isConnected || !inPage) return;
      event.preventDefault();
      if (state.collapsed) { state.collapsed = false; writeValue("collapsed", false); renderDock(); }
      if (state.open) closePanel(); else dockAction();
    }
  }, true);
  shadow.addEventListener("keydown", (event) => { if (event.key === "Escape" && state.open) closePanel(); });

  try {
    if (typeof GM_registerMenuCommand === "function") {
      GM_registerMenuCommand("NSFWDL settings", () => {
        ensureWidget();
        state.collapsed = false;
        writeValue("collapsed", false);
        state.view = "settings";
        openPanel();
      });
    }
  } catch (_) { /* optional */ }

  // ── Page tracking ──────────────────────────────────────────────────────
  // The dock shows on single-video pages and while a RedGifs feed has a
  // video on screen, and also elsewhere while it has
  // downloads to show (a thumbnail started one, or the site changed pages
  // without reloading).
  function ensureWidget() {
    if (!host.isConnected && document.body) document.body.appendChild(host);
  }

  let lastHref = "";
  let lastVideo = null;
  let lastListing = false;
  function sync() {
    const video = currentVideoUrl(site, location.href, document);
    const listing = checkListing();
    if (location.href === lastHref && video === lastVideo && listing === lastListing) return;
    // The site moved to another page without reloading: the picks were for the old one.
    if (lastHref && location.href !== lastHref && state.bulk.selecting) stopSelecting(true);
    lastHref = location.href;
    lastVideo = video;
    lastListing = listing;
    const onVideo = Boolean(video);
    state.pageUrl = video;
    if (onVideo || listing || state.jobs.length || state.open) {
      ensureWidget();
      renderDock();
      if (state.open && state.view === "pick" && onVideo && state.target && state.target.url !== state.pageUrl && !state.target.loading) render();
    } else if (host.isConnected) {
      closePanel();
      host.remove();
    }
  }
  renderDock();
  sync();
  // The SPA sync runs slower while the tab is hidden and catches up as soon
  // as it is visible again. try/finally: one throwing sync() must never stop
  // the chain.
  let syncTimer = 0;
  function scheduleSync() {
    clearTimeout(syncTimer);
    syncTimer = setTimeout(() => { try { sync(); } finally { scheduleSync(); } }, syncDelay());
  }
  scheduleSync();
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) return;
    try { sync(); } finally { scheduleSync(); }
    if (supporterToken()) refreshSupporterEntitlement();
  });
  // Back from nsfwdl.com (say, after buying a key there): unlock an open
  // panel without a reload when the site now has a key for this browser.
  document.addEventListener("visibilitychange", () => {
    if (document.hidden || supporterToken()) return;
    siteLinkAt = 0;
    if (!state.open) return;
    linkFromSite().then((linked) => {
      if (!linked) return;
      resetTargetLocks();
      if (state.bulk.config) state.bulk.configAt = 0;
      render();
    });
  });
  scheduleMarks();
})();

