// Unattended SourceCapsule capture.
//
//   node scripts/sourcecapsule-capture.mjs --url "https://x.com/handle/status/123" --json
//   node scripts/sourcecapsule-capture.mjs --reload   (load a rebuilt dist/ without a restart)
//
// Structured JSON goes to stdout, progress and diagnostics to stderr, nonzero exit on
// failure. The CLI never touches X itself: it hands the URL to the extension through the
// native messaging host and prints what comes back.
'use strict';

import fs from 'node:fs';
import net from 'node:net';
import process from 'node:process';
import { pathToFileURL } from 'node:url';

// Windows named pipe path: \\.\pipe\sourcecapsule-capture
const DEFAULT_PIPE = String.raw`\\.\pipe\sourcecapsule-capture`;
// Tests (and any parallel install) can point at their own pipe so they never fight
// the host the browser already has running.
const PIPE = process.env.SOURCECAPSULE_PIPE || DEFAULT_PIPE;
const DEFAULT_TIMEOUT_MS = 5 * 60 * 1000;
const CONNECT_RETRIES = 3;
const CONNECT_RETRY_DELAY_MS = 750;
// A reloaded worker reconnects at start; the 30s reconnect alarm is the backstop.
const RELOAD_WAIT_MS = 45000;

// Only a canonical post permalink is accepted. Anything else (search pages, profiles,
// redirect shorteners) would either fail downstream or capture the wrong thing.
const CANONICAL_X_URL =
  /^https:\/\/(?:www\.|mobile\.)?(?:x|twitter)\.com\/([A-Za-z0-9_]{1,15})\/status\/(\d{1,25})(?:[/?#].*)?$/;

// The extension and the host both cap the capture at 900s, so a larger value would only
// promise more than it can deliver. The Worker accepts exactly these expiries.
const MAX_TIMEOUT_SECONDS = 900;
const VALID_EXPIRY_DAYS = [1, 7, 30];

function numericValue(flag, raw) {
  // Number('') is 0 and Number('5m') is NaN, so check the text, not the conversion.
  if (raw === undefined || !/^\d+(?:\.\d+)?$/.test(raw)) {
    throw new Error(`${flag} needs a number, got ${raw === undefined ? 'nothing' : `"${raw}"`}.`);
  }
  return Number(raw);
}

function parseArgs(argv) {
  const args = { json: false, timeoutMs: DEFAULT_TIMEOUT_MS };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    // JSON is the only output format; the flag is accepted so existing callers keep working.
    if (arg === '--json') args.json = true;
    else if (arg === '--url') args.url = argv[++i];
    else if (arg === '--ping') args.ping = true;
    else if (arg === '--reload') args.reload = true;
    else if (arg === '--timeout') {
      const seconds = numericValue('--timeout', argv[++i]);
      if (seconds < 1 || seconds > MAX_TIMEOUT_SECONDS) {
        throw new Error(`--timeout must be between 1 and ${MAX_TIMEOUT_SECONDS} seconds.`);
      }
      args.timeoutMs = seconds * 1000;
    } else if (arg === '--expiry-days') {
      const days = numericValue('--expiry-days', argv[++i]);
      if (!VALID_EXPIRY_DAYS.includes(days)) {
        throw new Error(`--expiry-days must be one of ${VALID_EXPIRY_DAYS.join(', ')}.`);
      }
      args.expiryDays = days;
    } else throw new Error(`Unknown argument: ${arg}`);
  }
  return args;
}

export function canonicalXUrl(value) {
  const match = CANONICAL_X_URL.exec(String(value || '').trim());
  if (!match) return null;
  return { url: `https://x.com/${match[1]}/status/${match[2]}`, handle: match[1], id: match[2] };
}

// stdout carries the contract and nothing else. The transport's correlation id and any
// future envelope fields stay on this side of the boundary.
const RESULT_FIELDS = [
  'ok',
  'sourceUrl',
  'viewUrl',
  'markdownUrl',
  'expiresAt',
  'complete',
  'capturedPosts',
  'conversation',
  'warnings',
  'error',
  'message',
  'blockers',
  'counts',
];

export function formatResult(reply) {
  const out = {};
  for (const field of RESULT_FIELDS) {
    if (reply && Object.prototype.hasOwnProperty.call(reply, field)) out[field] = reply[field];
  }
  if (out.ok && !Array.isArray(out.warnings)) out.warnings = [];
  return out;
}

// --ping and --reload replies get the same treatment: an allowlist, never the raw envelope.
const CONTROL_FIELDS = [
  'ok',
  'extensionVersion',
  'extensionId',
  'reloading',
  'reloaded',
  'error',
  'message',
];

export function formatControlReply(reply) {
  const out = {};
  for (const field of CONTROL_FIELDS) {
    if (reply && Object.prototype.hasOwnProperty.call(reply, field)) out[field] = reply[field];
  }
  return out;
}

function progress(...parts) {
  process.stderr.write(`[sourcecapsule] ${parts.join(' ')}\n`);
}

function connectOnce() {
  return new Promise((resolve, reject) => {
    const socket = net.connect(PIPE);
    socket.once('connect', () => resolve(socket));
    socket.once('error', reject);
  });
}

async function connectWithRetry() {
  let lastError;
  for (let attempt = 1; attempt <= CONNECT_RETRIES; attempt++) {
    try {
      return await connectOnce();
    } catch (error) {
      lastError = error;
      progress(
        `host not reachable (attempt ${attempt}/${CONNECT_RETRIES}): ${error.code || error.message}`
      );
      if (attempt < CONNECT_RETRIES) {
        await new Promise((resolve) => setTimeout(resolve, CONNECT_RETRY_DELAY_MS));
      }
    }
  }
  // Almost always the same cause: the browser is running, but it was started without
  // --load-extension, so the extension is not loaded at all and no service worker ever
  // opened the native port. Say that, and say the fix, rather than "host unreachable".
  throw new Error(
    `Cannot reach the SourceCapsule native host (${lastError && lastError.code}). ` +
      'The browser is probably running without the extension: a start that lacks ' +
      '--load-extension does not reload a command-line-installed extension. Run ' +
      'powershell -ExecutionPolicy Bypass -File scripts\\start-sourcecapsule-browser.ps1 -Status ' +
      'to check, and add -Restart -Verify to fix it.'
  );
}

async function request(payload, timeoutMs) {
  const socket = await connectWithRetry();
  return await new Promise((resolve, reject) => {
    let buffer = '';
    const timer = setTimeout(() => {
      socket.destroy();
      reject(new Error(`No reply from the extension within ${Math.round(timeoutMs / 1000)}s.`));
    }, timeoutMs + 5000);
    socket.setEncoding('utf8');
    socket.on('data', (chunk) => {
      buffer += chunk;
      const index = buffer.indexOf('\n');
      if (index < 0) return;
      clearTimeout(timer);
      socket.end();
      try {
        resolve(JSON.parse(buffer.slice(0, index)));
      } catch (error) {
        reject(new Error(`Malformed reply from host: ${error.message}`));
      }
    });
    socket.on('error', (error) => {
      clearTimeout(timer);
      reject(error);
    });
    // The host dies with its browser. A clean close before any reply used to leave this
    // promise pending until the timer, up to five minutes. Rejecting after the reply
    // already resolved is a no-op, so the normal path is unaffected.
    socket.on('close', () => {
      clearTimeout(timer);
      reject(new Error('The native host closed the connection before replying.'));
    });
    socket.write(`${JSON.stringify(payload)}\n`);
  });
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

  if (args.ping) {
    progress('pinging extension through the native host');
    const reply = await request({ id, action: 'ping', timeoutMs: 15000 }, 15000);
    process.stdout.write(`${JSON.stringify(formatControlReply(reply), null, 2)}\n`);
    return reply.ok ? 0 : 1;
  }

  if (args.reload) {
    progress('asking the extension to reload itself');
    const ask = await request({ id, action: 'reload', timeoutMs: 15000 }, 15000);
    if (!ask.ok) {
      if (ask.error === 'unknown_action') {
        ask.message =
          'The running extension predates --reload. Reload it once from brave://extensions (or restart with the launcher); later builds can reload themselves.';
      }
      process.stdout.write(`${JSON.stringify(formatControlReply(ask), null, 2)}\n`);
      return 1;
    }
    // The old worker and its host go away; the new worker starts its own host. Wait for it.
    const deadline = Date.now() + RELOAD_WAIT_MS;
    let lastError;
    await new Promise((resolve) => setTimeout(resolve, 1500));
    while (Date.now() < deadline) {
      try {
        const pong = await request({ id: `${id}-p`, action: 'ping', timeoutMs: 5000 }, 5000);
        if (pong.ok) {
          progress('extension reloaded and answering');
          process.stdout.write(
            `${JSON.stringify(formatControlReply({ ...pong, reloaded: true }), null, 2)}\n`
          );
          return 0;
        }
        lastError = new Error(pong.message || pong.error);
      } catch (error) {
        lastError = error;
      }
      await new Promise((resolve) => setTimeout(resolve, 1000));
    }
    throw new Error(
      `The extension did not answer within ${RELOAD_WAIT_MS / 1000}s of reloading: ${
        lastError ? lastError.message : 'no reply'
      }`
    );
  }

  const canonical = canonicalXUrl(args.url);
  if (!canonical) {
    throw new Error(
      'A canonical post URL is required, e.g. https://x.com/handle/status/1234567890.'
    );
  }
  progress(`capturing ${canonical.url}`);
  const reply = await request(
    {
      id,
      action: 'capture-share',
      url: canonical.url,
      expiryDays: args.expiryDays,
      timeoutMs: args.timeoutMs,
    },
    args.timeoutMs
  );
  process.stdout.write(`${JSON.stringify(formatResult(reply), null, 2)}\n`);
  return reply.ok ? 0 : 1;
}

// Only run when invoked directly, so tests can import canonicalXUrl without side effects.
// import.meta.url is the REAL path, so resolve argv[1] too: through a junction or symlink the
// two differ, main() never ran, and the CLI exited 0 with empty stdout.
function isInvokedDirectly() {
  if (!process.argv[1]) return false;
  let entry = process.argv[1];
  try {
    entry = fs.realpathSync(entry);
  } catch {
    /* fall back to the path as given */
  }
  return import.meta.url === pathToFileURL(entry).href;
}
const invokedDirectly = isInvokedDirectly();

if (invokedDirectly) {
  main()
    .then((code) => process.exit(code))
    .catch((error) => {
      progress(`failed: ${error.message}`);
      process.stdout.write(
        `${JSON.stringify({ ok: false, error: 'cli_error', message: error.message }, null, 2)}\n`
      );
      process.exit(1);
    });
}

