// only the back-link record survives). After this it is hard-deleted entirely.
const TOMBSTONE_RETENTION_DAYS = 180;
// sha256 of the one inline script the client emits into content.html (the image lightbox).
// test/share-worker.test.mjs recomputes this from the userscript's real output, so editing
// the lightbox without adding its new hash here fails CI instead of breaking live capsules.
const LIGHTBOX_SCRIPT_HASHES = ['sha256-HjElcqBn7MgmOv/l9JPXAySq0NbP7jhuXip+wJwhr7g='];
const CONTENT_HTML_CSP = [
  "default-src 'none'",
  "img-src 'self' data:",
  "media-src 'self'",
  "style-src 'unsafe-inline'",
  `script-src ${LIGHTBOX_SCRIPT_HASHES.map((hash) => `'${hash}'`).join(' ')}`,
  "base-uri 'none'",
  "form-action 'none'",
  "frame-ancestors 'none'",
].join('; ');
const META_KEY_PATTERN = /^capsules\/([a-f0-9]{32})\/_meta\.json$/;
const SOURCE_URL_PATTERN =
  /^https:\/\/(?:x|twitter)\.com\/([A-Za-z0-9_]{1,15})\/status\/([0-9]{1,20})(?:\/(?:photo|video)\/[0-9]{1,2})?\/?$/;

function corsHeaders(request) {
  const origin = request.headers.get('Origin') || '*';
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Headers': 'Authorization, Content-Type',
    'Access-Control-Allow-Methods': 'GET, HEAD, POST, PUT, DELETE, OPTIONS',
    Vary: 'Origin',
  };
}

function json(request, value, status = 200) {
  return new Response(JSON.stringify(value), {
    status,
    headers: { 'Content-Type': 'application/json;charset=utf-8', ...corsHeaders(request) },
  });
}

function randomToken(bytes = 16) {
  const data = new Uint8Array(bytes);
  crypto.getRandomValues(data);
  return Array.from(data, (value) => value.toString(16).padStart(2, '0')).join('');
}

async function tokenHash(value) {
  const bytes = new TextEncoder().encode(String(value || ''));
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
  return Array.from(digest, (item) => item.toString(16).padStart(2, '0')).join('');
}

function metaKey(id) {
  return `capsules/${id}/_meta.json`;
}

function fileKey(id, path) {
  return `capsules/${id}/${path}`;
}

function validId(id) {
  return /^[a-f0-9]{32}$/.test(String(id || ''));
}

function validFilePath(path) {
  return (
    path === 'content.html' ||
    path === 'content.md' ||
    path === 'manifest.json' ||
    // Image files only, and never a name starting with "_": the client uploads nothing else
    // (media ids are alphanumeric), and "_meta.json" is the Worker's own record name.
    /^media\/[A-Za-z0-9][A-Za-z0-9._-]{0,179}\.(?:jpe?g|png|gif|webp|avif)$/i.test(path)
  );
}

// Only a canonical public X post permalink is ever stored or emitted. Anything else is
// dropped, so an expired capsule can never be used to redirect a reader somewhere else.
function sanitizeSourceUrl(value) {
  const raw = String(value || '').trim();
  const match = SOURCE_URL_PATTERN.exec(raw);
  return match ? `https://x.com/${match[1]}/status/${match[2]}` : '';
}

function sanitizeLabel(value, max = 200) {
  return (
    String(value || '')
      // eslint-disable-next-line no-control-regex
      .replace(/[\u0000-\u001f\u007f]/g, ' ')
      .trim()
      .slice(0, max)
  );
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function mimeFromPath(path) {
  const clean = String(path || '')
    .split('?')[0]
    .toLowerCase();
  if (clean.endsWith('.html')) return 'text/html;charset=utf-8';
  if (clean.endsWith('.md')) return 'text/markdown;charset=utf-8';
  if (clean.endsWith('.json')) return 'application/json;charset=utf-8';
  if (clean.endsWith('.jpg') || clean.endsWith('.jpeg')) return 'image/jpeg';
  if (clean.endsWith('.png')) return 'image/png';
  if (clean.endsWith('.webp')) return 'image/webp';
  if (clean.endsWith('.gif')) return 'image/gif';
  if (clean.endsWith('.avif')) return 'image/avif';
  if (clean.endsWith('.mp4')) return 'video/mp4';
  return '';
}

// The Worker decides how a stored file is served, never the uploader. Fixed paths get the
// type for their name. Anything under media/ is served inline only when its extension is an
// image or mp4 type; every other extension (.html, .svg, .bin, ...) comes back as an opaque
// download.
function servedType(path) {
  const inferred = mimeFromPath(path);
  if (path.startsWith('media/')) {
    return /^(image\/(?!svg)|video\/mp4)/.test(inferred) ? inferred : '';
  }
  return inferred;
}

async function getMeta(env, id) {
  const object = await env.CAPSULES.get(metaKey(id));
  if (!object) return null;
  const meta = JSON.parse(await object.text());
  meta._custom = object.customMetadata || {};
  return meta;
}

async function authorized(request, env, id) {
  const meta = await getMeta(env, id);
  if (!meta) return { ok: false, status: 404, meta: null };
  const value = (request.headers.get('Authorization') || '').replace(/^Bearer\s+/i, '');
  const hash = value ? await tokenHash(value) : '';
  return {
    ok: Boolean(hash && hash === meta._custom.tokenHash),
    status: hash ? 403 : 401,
    meta,
  };
}

async function putMeta(env, meta, tokenHashValue, status) {
  const publicMeta = { ...meta };
  delete publicMeta._custom;
  await env.CAPSULES.put(metaKey(meta.id), JSON.stringify(publicMeta), {
    httpMetadata: { contentType: 'application/json;charset=utf-8' },
    // expiresAt is duplicated into customMetadata so the daily cleanup can read it
    // straight off a list page. Without it the cron needs one GET per capsule, which
    // grows without bound as tombstones accumulate.
    customMetadata: {
      tokenHash: tokenHashValue,
      status,
      expiresAt: String(meta.expiresAt || ''),
    },
  });
}

async function deletePrefix(env, prefix, keepKey = '') {
  let cursor;
  do {
    const page = await env.CAPSULES.list({ prefix, cursor });
    const keys = (page.objects || []).map((object) => object.key).filter((key) => key !== keepKey);
    if (keys.length) await env.CAPSULES.delete(keys);
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
}

async function capsuleBytes(env, id, excludingKey = '') {
  let total = 0;
  let cursor;
  do {
    const page = await env.CAPSULES.list({ prefix: `capsules/${id}/`, cursor });
    for (const object of page.objects || []) {
      if (object.key !== metaKey(id) && object.key !== excludingKey) {
        total += Number(object.size || 0);
      }
    }
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
  return total;
}

function isExpired(meta) {
  return !meta || !meta.expiresAt || Date.parse(meta.expiresAt) <= Date.now();
}

function isTombstone(meta) {
  return Boolean(meta && meta._custom && meta._custom.status === 'expired');
}

function tombstoneWornOut(meta, now = Date.now()) {
  const expired = Date.parse((meta && meta.expiredAt) || (meta && meta.expiresAt));
  if (!Number.isFinite(expired)) return true;
  return now - expired > TOMBSTONE_RETENTION_DAYS * 86400000;
}

// Expiry deletes the capsule's content but keeps a small record pointing back at the
// original X post, so a reader who opens a dead link is not left at a bare 410. A
// capsule with no recorded source URL has nothing worth keeping and is fully deleted.
async function expireCapsule(env, meta) {
  const id = meta.id;
  const prefix = `capsules/${id}/`;
  const published = Boolean(meta._custom && meta._custom.status === 'published');
  // An upload session abandoned before finalize was never a link anyone holds, so it
  // leaves nothing behind.
  if (!published || !sanitizeSourceUrl(meta.sourceUrl)) {
    await deletePrefix(env, prefix);
    return;
  }
  await deletePrefix(env, prefix, metaKey(id));
  const tombstone = {
    id,
    createdAt: meta.createdAt,
    expiresAt: meta.expiresAt,
    expiredAt: meta.expiredAt || new Date().toISOString(),
    expiryDays: meta.expiryDays,
    sourceUrl: meta.sourceUrl,
    title: meta.title || '',
    handle: meta.handle || '',
  };
  // The delete token is retained so the creator's "Delete link" still hard-deletes the
  // tombstone. Re-upload and re-finalize are blocked separately by the expiry checks.
  await putMeta(env, tombstone, (meta._custom && meta._custom.tokenHash) || '', 'expired');
}

async function createCapsule(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json(request, { error: 'Expected JSON body.' }, 400);
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return json(request, { error: 'Expected a JSON object.' }, 400);
  }
  const expiryDays = Number(body.expiryDays);
  if (!VALID_EXPIRY_DAYS.has(expiryDays)) {
    return json(request, { error: 'expiryDays must be 1, 7, or 30.' }, 400);
  }
  const id = randomToken(16);
  const uploadToken = randomToken(24);
  const createdAt = new Date().toISOString();
  const expiresAt = new Date(Date.now() + expiryDays * 86400000).toISOString();
  const origin = new URL(request.url).origin;
  // An unrecognised sourceUrl is dropped rather than rejected: the capsule itself is
  // still worth publishing, it just expires without a back-link.
  const sourceUrl = sanitizeSourceUrl(body.sourceUrl);
  const meta = {
    id,
    createdAt,
    expiresAt,
    expiryDays,
    sourceUrl,
    title: sanitizeLabel(body.title),
    handle: sanitizeLabel(body.handle, 40),
  };
  await putMeta(env, meta, await tokenHash(uploadToken), 'uploading');
  return json(
    request,
    {
      id,
      uploadToken,
      deleteToken: uploadToken,
      uploadUrl: `${origin}/api/capsules/${id}/files`,
      finalizeUrl: `${origin}/api/capsules/${id}/finalize`,
      deleteUrl: `${origin}/api/capsules/${id}`,
      viewUrl: `${origin}/c/${id}`,
      markdownUrl: `${origin}/c/${id}.md`,
      expiresAt,
      sourceUrl,
    },
    201
  );
}

// Reads a request body but gives up as soon as it passes `limit` bytes, so an oversized or
// endless chunked upload is cut off instead of buffered whole. Returns null when over limit.
async function readBodyCapped(request, limit) {
  if (!request.body) return new Uint8Array(0);
  const reader = request.body.getReader();
  const chunks = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > limit) {
      await reader.cancel().catch(() => {});
      return null;
    }
    chunks.push(value);
  }
  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return bytes;
}

async function uploadFile(request, env, id, path) {
  const auth = await authorized(request, env, id);
  if (!auth.ok) return json(request, { error: 'Upload authorization failed.' }, auth.status);
  if (isExpired(auth.meta)) return json(request, { error: 'Upload session expired.' }, 410);
  // Only an open upload session accepts files. A published capsule is immutable, so a
  // leaked token can delete it but not rewrite what readers see.
  if (auth.meta._custom.status !== 'uploading') {
    return json(request, { error: 'Capsule is not accepting uploads.' }, 409);
  }
  if (!validFilePath(path)) return json(request, { error: 'Invalid file path.' }, 400);
  if (!(await uploadAllowed(env, id))) {
    return json(request, { error: 'Too many uploads for this capsule. Try again shortly.' }, 429);
  }
  const length = Number(request.headers.get('Content-Length') || 0);
  if (length > MAX_CAPSULE_BYTES) return json(request, { error: 'File is too large.' }, 413);
  const key = fileKey(id, path);
  const existingBytes = await capsuleBytes(env, id, key);
  const bytes = await readBodyCapped(request, Math.max(0, MAX_CAPSULE_BYTES - existingBytes));
  if (!bytes) return json(request, { error: 'Capsule exceeds the 25 MB limit.' }, 413);
  await env.CAPSULES.put(key, bytes, {
    httpMetadata: { contentType: servedType(path) || 'application/octet-stream' },
  });
  return json(request, { ok: true, path, bytes: bytes.byteLength });
}

async function finalizeCapsule(request, env, id) {
  const auth = await authorized(request, env, id);
  if (!auth.ok) return json(request, { error: 'Publish authorization failed.' }, auth.status);
  if (isExpired(auth.meta)) return json(request, { error: 'Upload session expired.' }, 410);
  for (const required of ['content.html', 'content.md', 'manifest.json']) {
    if (!(await env.CAPSULES.head(fileKey(id, required)))) {
      return json(request, { error: `Missing required file: ${required}` }, 409);
    }
  }
  if ((await capsuleBytes(env, id)) > MAX_CAPSULE_BYTES) {
    return json(request, { error: 'Capsule exceeds the 25 MB limit.' }, 413);
  }
  await putMeta(env, auth.meta, auth.meta._custom.tokenHash, 'published');
  return json(request, { ok: true, id, expiresAt: auth.meta.expiresAt });
}

async function deleteCapsule(request, env, id) {
  const auth = await authorized(request, env, id);
  if (!auth.ok) return json(request, { error: 'Delete authorization failed.' }, auth.status);
  await deletePrefix(env, `capsules/${id}/`);
  return json(request, { ok: true });
}

function publicPath(pathname, id) {
  const base = `/c/${id}`;
  if (pathname === base) return 'content.html';
  if (pathname === `${base}.md`) return 'content.md';
  if (pathname === `${base}/manifest.json`) return 'manifest.json';
  const mediaPrefix = `${base}/media/`;
  if (pathname.startsWith(mediaPrefix)) {
    let name;
    try {
      name = decodeURIComponent(pathname.slice(mediaPrefix.length));
    } catch {
      return '';
    }
    return /^[-A-Za-z0-9._]{1,180}$/.test(name) ? `media/${name}` : '';
  }
  return '';
}

function readableDate(value) {
  const time = Date.parse(value);
  if (!Number.isFinite(time)) return 'an earlier date';
  return new Date(time).toISOString().slice(0, 10);
}

function tombstoneHtml(meta) {
  const source = sanitizeSourceUrl(meta.sourceUrl);
  const title = sanitizeLabel(meta.title) || 'An X post';
  const handle = sanitizeLabel(meta.handle, 40);
  const byline = handle ? ` by ${escapeHtml(handle)}` : '';
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>This SourceCapsule link has expired</title>
<style>
  :root { color-scheme: light dark; --bg:#ffffff; --fg:#15202b; --muted:#5b7083; --line:#e1e8ed; --accent:#1d9bf0; }
  @media (prefers-color-scheme: dark) {
    :root { --bg:#15202b; --fg:#f7f9f9; --muted:#8899a6; --line:#38444d; --accent:#1d9bf0; }
  }
  body { margin:0; background:var(--bg); color:var(--fg); font:16px/1.6 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
  main { max-width:34rem; margin:0 auto; padding:3rem 1.25rem; }
  h1 { font-size:1.35rem; margin:0 0 .75rem; }
  p { margin:0 0 1rem; color:var(--muted); }
  .card { border:1px solid var(--line); border-radius:12px; padding:1.25rem; margin:1.5rem 0; }
  .card p { color:var(--fg); margin:0 0 .5rem; font-weight:600; }
  a.source { display:inline-block; color:var(--accent); word-break:break-all; }
  footer { border-top:1px solid var(--line); padding-top:1rem; font-size:.85rem; color:var(--muted); }
</style></head>
<body><main>
<h1>This SourceCapsule link has expired</h1>
<p>The archived copy was deleted on ${escapeHtml(readableDate(meta.expiredAt || meta.expiresAt))}, as set when the link was created. The original post is still on X.</p>
<div class="card">
<p>${escapeHtml(title)}${byline}</p>
<a class="source" href="${escapeHtml(source)}" rel="noopener noreferrer nofollow">${escapeHtml(source)}</a>
</div>
<footer>SourceCapsule keeps only this back-link after a shared capsule expires. No copy of the post remains on this server.</footer>
</main></body></html>`;
}

function tombstoneMarkdown(meta) {
  const source = sanitizeSourceUrl(meta.sourceUrl);
  const title = sanitizeLabel(meta.title) || 'An X post';
  const handle = sanitizeLabel(meta.handle, 40);
  const lines = [
    '# This SourceCapsule link has expired',
    '',
    `The archived copy was deleted on ${readableDate(meta.expiredAt || meta.expiresAt)}, as set when the link was created.`,
    'No copy of the post remains on this server. The original post is still on X:',
    '',
    `- Post: ${title}`,
  ];
  if (handle) lines.push(`- Author: ${handle}`);
  lines.push(`- Original: ${source}`, '');
  return lines.join('\n');
}

function tombstoneResponse(request, meta, path) {
  const markdown = path === 'content.md';
  const body = markdown ? tombstoneMarkdown(meta) : tombstoneHtml(meta);
  const headers = new Headers({
    'Content-Type': markdown ? 'text/markdown;charset=utf-8' : 'text/html;charset=utf-8',
    'Content-Length': String(new TextEncoder().encode(body).byteLength),
    'Cache-Control': 'public, max-age=300',
    'X-Robots-Tag': 'noindex, nofollow',
    'Referrer-Policy': 'no-referrer',
    'X-Content-Type-Options': 'nosniff',
  });
  if (!markdown) {
    headers.set(
      'Content-Security-Policy',
      "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'"
    );
  }
  return new Response(request.method === 'HEAD' ? null : body, { status: 410, headers });
}

async function serveCapsule(request, env, ctx, id, path) {
  const meta = await getMeta(env, id);
  if (!meta) return new Response('Capsule not found.', { status: 404 });
  if (isTombstone(meta)) return tombstoneResponse(request, meta, path);
  if (meta._custom.status !== 'published') {
    return new Response('Capsule not found.', { status: 404 });
  }
  if (isExpired(meta)) {
    // Serve the tombstone straight away; the content deletion it describes runs after
    // the response, so the reader never waits on an R2 sweep.
    const expired = { ...meta, expiredAt: new Date().toISOString() };
    if (ctx && ctx.waitUntil) ctx.waitUntil(expireCapsule(env, expired));
    if (sanitizeSourceUrl(meta.sourceUrl)) return tombstoneResponse(request, expired, path);
    return new Response('This SourceCapsule link has expired.', { status: 410 });
  }
  const object = await env.CAPSULES.get(fileKey(id, path));
  if (!object) return new Response('File not found.', { status: 404 });
  const headers = new Headers();
  object.writeHttpMetadata && object.writeHttpMetadata(headers);
  // Ignore whatever type was stored with the object (older uploads kept the uploader's).
  const type = servedType(path);
  headers.set('Content-Type', type || 'application/octet-stream');
  if (!type) headers.set('Content-Disposition', 'attachment');
  // R2's writeHttpMetadata omits Content-Length; without it, HEAD probes from
  // Slack, Discord, and Twitter link-preview crawlers can skip the asset (they
  // won't fetch an unknown-size body over their preview budget). Serve the size
  // explicitly on every response so previews render and clients can show progress.
  if (typeof object.size === 'number' && Number.isFinite(object.size)) {
    headers.set('Content-Length', String(object.size));
  }
  headers.set('Cache-Control', 'public, max-age=300');
  // noindex/nofollow keep unlisted capsules out of search results. Deliberately
  // NOT noarchive: several AI browsing stacks read noarchive as "may not retain
  // this content" and refuse to fetch at all, which breaks the one thing an
  // AI-readable share link exists for. Do not add it back.
  headers.set('X-Robots-Tag', 'noindex, nofollow');
  headers.set('Referrer-Policy', 'no-referrer');
  headers.set('X-Content-Type-Options', 'nosniff');
  headers.set(
    'Content-Security-Policy',
    path === 'content.html'
      ? CONTENT_HTML_CSP
      : "default-src 'none'; sandbox; frame-ancestors 'none'"
  );
  return new Response(request.method === 'HEAD' ? null : object.body, { headers });
}

// An IPv6 customer controls a whole /64, so keying on the full address lets one client
// rotate through 2^64 keys. Collapse IPv6 to its /64 prefix; IPv4 stays as is.
function limiterKey(ip) {
  if (!ip.includes(':')) return ip;
  const [head, tail = ''] = ip.split('::');
  const headGroups = head ? head.split(':') : [];
  const tailGroups = tail ? tail.split(':') : [];
  const fill = Array(Math.max(0, 8 - headGroups.length - tailGroups.length)).fill('0');
  const groups = ip.includes('::') ? [...headGroups, ...fill, ...tailGroups] : headGroups;
  const prefix = groups.slice(0, 4).map((group) => group.toLowerCase().padStart(4, '0'));
  return `${prefix.join(':')}::/64`;
}

async function createAllowed(request, env) {
  // CREATE_LIMITER is a Workers rate-limiting binding; absent in local dev and tests.
  if (!env.CREATE_LIMITER) return true;
  const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
  const { success } = await env.CREATE_LIMITER.limit({ key: limiterKey(ip) });
  return success;
}

// Per-capsule upload limit, sized for the client's ~40-file burst. Checked after the
// bearer token so a stranger who knows an id cannot burn that capsule's budget.
async function uploadAllowed(env, id) {
  if (!env.UPLOAD_LIMITER) return true;
  const { success } = await env.UPLOAD_LIMITER.limit({ key: id });
  return success;
}

async function handleRequest(request, env, ctx) {
  if (request.method === 'OPTIONS') return new Response(null, { headers: corsHeaders(request) });
  const url = new URL(request.url);
  let segments;
  try {
    segments = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
  } catch {
    // A stray "%" or truncated escape is the caller's mistake, not a Worker failure.
    return json(request, { error: 'Malformed path.' }, 400);
  }
  if (request.method === 'POST' && url.pathname === '/api/capsules') {
    if (!(await createAllowed(request, env))) {
      return json(
        request,
        { error: 'Too many new share links from this address. Try again in a minute.' },
        429
      );
    }
    return createCapsule(request, env);
  }
  if (segments[0] === 'api' && segments[1] === 'capsules' && validId(segments[2])) {
    const id = segments[2];
    if (request.method === 'PUT' && segments[3] === 'files') {
      return uploadFile(request, env, id, segments.slice(4).join('/'));
    }
    if (request.method === 'POST' && segments[3] === 'finalize') {
      return finalizeCapsule(request, env, id);
    }
    if (request.method === 'DELETE' && segments.length === 3) {
      return deleteCapsule(request, env, id);
    }
  }
  const match = url.pathname.match(/^\/c\/([a-f0-9]{32})(?:\.md|\/.*)?$/);
  if (match && (request.method === 'GET' || request.method === 'HEAD')) {
    const path = publicPath(url.pathname, match[1]);
    if (path) return serveCapsule(request, env, ctx, match[1], path);
  }
  if (url.pathname === '/health')
    return json(request, { ok: true, service: 'sourcecapsule-share' });
  return new Response('Not found.', { status: 404 });
}

async function cleanupExpired(env) {
  let cursor;
  const now = Date.now();
  do {
    // include customMetadata so the common case (a live capsule, or a tombstone still
    // within retention) costs no extra read at all - only the objects that actually
    // need work are fetched.
    const page = await env.CAPSULES.list({
      prefix: 'capsules/',
      cursor,
      include: ['customMetadata'],
    });
    // Only the Worker's own record at capsules/<id>/_meta.json counts. Anything else that
    // happens to end in "_meta.json" (e.g. an uploaded media/_meta.json) is ignored.
    const metaObjects = (page.objects || []).filter((object) => META_KEY_PATTERN.test(object.key));
    for (const item of metaObjects) {
      // One bad capsule (a corrupt _meta.json, a failing delete) must not abort the sweep:
      // it would stall on the same item every day and nothing behind it would ever expire.
      try {
        const custom = item.customMetadata || {};
        if (custom.status === 'expired') {
          // Second stage: a tombstone that has outlived its retention window is removed.
          // Retention is measured from the capsule's original expiry, which is the moment
          // its content was deleted.
          if (tombstoneWornOut({ expiresAt: custom.expiresAt || '' }, now)) {
            await deletePrefix(env, item.key.slice(0, -'_meta.json'.length));
          }
          continue;
        }
        // Old objects written before expiresAt was mirrored into customMetadata still
        // need a read; anything not yet due is skipped without one.
        if (custom.expiresAt && Date.parse(custom.expiresAt) > now) continue;
        const object = await env.CAPSULES.get(item.key);
        if (!object) continue;
        const meta = JSON.parse(await object.text());
        // The id comes from the key, never from the stored body.
        meta.id = META_KEY_PATTERN.exec(item.key)[1];
        meta._custom = object.customMetadata || {};
        if (isExpired(meta)) {
          await expireCapsule(env, { ...meta, expiredAt: new Date(now).toISOString() });
        }
      } catch (error) {
        console.error(
          `cleanupExpired: skipped ${item.key}: ${error && error.message ? error.message : error}`
        );
      }
    }
    cursor = page.truncated ? page.cursor : undefined;
  } while (cursor);
}

export { cleanupExpired, handleRequest };

export default {
  fetch: handleRequest,
  scheduled(_event, env, ctx) {
    ctx.waitUntil(cleanupExpired(env));
  },
};

