/**
 * 哈基米积分助手（纯原生 Microsoft Edge MV3 扩展） - 后台核心引擎
 *
 * 100% 零 Python / 零本地端口 / 零断连：
 * - 打开 Edge 自动检查今日任务，在屏幕右下角弹出精致独立小窗（chrome.windows.create popup）并自动运行；
 * - 复用用户已登录的真实 Edge Cookie 与单后台标签页（active: false），不打扰浏览；
 * - 支持每日打卡、日常浏览、+100/+5 拼图自动跳过、低频拟人必应搜索、15 分钟冷却自适应与安全熔断。
 */

import { DEFAULT_CONFIG, RISK_PROFILES, pickNaturalQuery } from "./core/profiles.js";
import { parseRewardsBundle } from "./core/parser.js";

const KEEPALIVE_ALARM = "hakimi_mv3_keepalive";
const STORAGE_KEY_CONFIG = "hakimi_config_v2";
const STORAGE_KEY_HISTORY = "hakimi_history_v2";
const STORAGE_KEY_STATE = "hakimi_state_v2";

let workerTabId = null;
let panelWindowId = null;
let isRunning = false;
let stopRequested = false;
let isPaused = false;
let skipWaitRequested = false;
let logs = [];

let state = {
  state: "IDLE", // IDLE / RUNNING / COOLING / PAUSED / DONE / ALERT / STOPPED
  headline: "极其猫准备就绪啦",
  detail: "点击「开始运行」或开启「启动自跑」，极其猫会帮你低频拟人完成今日微软积分任务～",
  countdownText: "",
  countdownRemaining: 0,
  countdownTotal: 0,
  stepActivities: "pending",
  stepSearch: "pending",
  availablePoints: null,
  todayPoints: null,
  streakDays: null,
  dailyDone: 0,
  dailyTotal: 3,
  earnDone: 0,
  earnTotal: 0,
  searchEarned: 0,
  searchTarget: 60,
  searchMaxReported: 60,
  tasks: [],
  recentQueries: [],
  manualItems: [],
  lastGainPoints: 0,
  lastGainSeq: 0,
  alertMessage: "",
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const randInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
const todayKey = () => new Date().toISOString().slice(0, 10);

async function loadConfig() {
  const res = await chrome.storage.local.get(STORAGE_KEY_CONFIG);
  return { ...DEFAULT_CONFIG, ...(res[STORAGE_KEY_CONFIG] || {}) };
}

async function saveConfig(patch) {
  const cur = await loadConfig();
  const next = { ...cur, ...patch };
  await chrome.storage.local.set({ [STORAGE_KEY_CONFIG]: next });
  return next;
}

async function loadHistory() {
  const res = await chrome.storage.local.get(STORAGE_KEY_HISTORY);
  const data = res[STORAGE_KEY_HISTORY] || { days: {}, recentQueries: [] };
  if (!data.days) data.days = {};
  if (!Array.isArray(data.recentQueries)) data.recentQueries = [];
  return data;
}

async function saveHistory(data) {
  const keys = Object.keys(data.days || {}).sort();
  if (keys.length > 45) {
    for (const old of keys.slice(0, keys.length - 45)) delete data.days[old];
  }
  if (data.recentQueries.length > 600) {
    data.recentQueries = data.recentQueries.slice(-600);
  }
  await chrome.storage.local.set({ [STORAGE_KEY_HISTORY]: data });
}

function getTodayRec(history) {
  const k = todayKey();
  if (!history.days[k]) {
    history.days[k] = { doneIds: [], queriesToday: [], cooldowns: 0 };
  }
  return history.days[k];
}

async function persistState(patch = {}) {
  state = { ...state, ...patch };
  try {
    await chrome.storage.local.set({ [STORAGE_KEY_STATE]: { state, logs: logs.slice(-80) } });
  } catch (_) {}
}

function addLog(msg) {
  const now = new Date();
  const ts = now.toTimeString().slice(0, 8);
  logs.push(`[${ts}] ${msg}`);
  if (logs.length > 100) logs = logs.slice(-100);
  persistState();
}

function triggerGainFx(pts) {
  if (!pts || pts <= 0) return;
  state.lastGainPoints = pts;
  state.lastGainSeq += 1;
}

function notifyUser(title, message) {
  try {
    chrome.notifications.create({
      type: "basic",
      iconUrl: chrome.runtime.getURL("icons/icon128.png"),
      title,
      message,
    });
  } catch (_) {}
}

/**
 * 在屏幕右下角弹出精致小巧的原生独立看板窗口（自动贴合右下角，不挡主视野）。
 */
async function openOrFocusPanelWindow() {
  if (panelWindowId !== null) {
    try {
      const win = await chrome.windows.get(panelWindowId);
      if (win && win.id) {
        await chrome.windows.update(win.id, { focused: true });
        return;
      }
    } catch (_) {
      panelWindowId = null;
    }
  }

  let left = 960;
  let top = 220;
  const width = 430;
  const height = 640;
  try {
    const cur = await chrome.windows.getLastFocused();
    if (cur && typeof cur.left === "number" && typeof cur.width === "number" && typeof cur.top === "number" && typeof cur.height === "number") {
      left = Math.max(20, Math.round(cur.left + cur.width - width - 24));
      top = Math.max(20, Math.round(cur.top + cur.height - height - 24));
    }
  } catch (_) {}

  const created = await chrome.windows.create({
    url: chrome.runtime.getURL("panel.html"),
    type: "popup",
    width,
    height,
    left,
    top,
    focused: true,
  });
  panelWindowId = created.id;
}

async function fetchHtml(url) {
  try {
    const resp = await fetch(url, { credentials: "include", cache: "no-store", redirect: "follow" });
    const html = await resp.text();
    return { ok: resp.ok, finalUrl: resp.url || url, html };
  } catch (err) {
    return { ok: false, finalUrl: url, html: "", error: String(err?.message || err) };
  }
}

async function inspectRewards(full = true) {
  const reqs = full
    ? [
        fetchHtml("https://rewards.bing.com/dashboard"),
        fetchHtml("https://rewards.bing.com/earn"),
        fetchHtml("https://www.bing.com/rewardsapp/flyout?channel=bingflyout&partnerId=BingRewards"),
      ]
    : [
        Promise.resolve({ ok: true, finalUrl: "", html: "" }),
        fetchHtml("https://rewards.bing.com/earn"),
        fetchHtml("https://www.bing.com/rewardsapp/flyout?channel=bingflyout&partnerId=BingRewards"),
      ];

  const [dashRes, earnRes, flyRes] = await Promise.all(reqs);
  const checkUrl = `${dashRes.finalUrl} ${earnRes.finalUrl}`.toLowerCase();
  if (checkUrl.includes("login.live.com") || checkUrl.includes("login.microsoftonline.com")) {
    return { ok: false, alert: "LOGIN_REQUIRED", message: "检测到微软账号未登录，请先在 Edge 登录 Microsoft Rewards。" };
  }
  if (!dashRes.html && !earnRes.html && !flyRes.html) {
    return { ok: false, message: "网络拉取 Rewards 页面失败，请检查网络连接。" };
  }
  return parseRewardsBundle({
    dashboardHtml: dashRes.html,
    earnHtml: earnRes.html,
    flyoutHtml: flyRes.html,
  });
}

function isScriptableUrl(urlStr) {
  if (!urlStr) return false;
  const low = urlStr.toLowerCase();
  return (low.startsWith("https://") || low.startsWith("http://")) && !low.includes("microsoftedge.microsoft.com/addons");
}

async function ensureWorkerTab(initialUrl = "https://www.bing.com/") {
  if (workerTabId !== null) {
    try {
      const tab = await chrome.tabs.get(workerTabId);
      if (tab && tab.id) return { tabId: tab.id, justCreated: false };
    } catch (_) {
      workerTabId = null;
    }
  }
  const created = await chrome.tabs.create({ url: initialUrl, active: false });
  workerTabId = created.id;
  return { tabId: workerTabId, justCreated: true };
}

async function waitForTabComplete(tabId, expectedHost = null, timeoutMs = 26000) {
  const start = Date.now();
  await sleep(700);
  while (Date.now() - start < timeoutMs) {
    const tab = await chrome.tabs.get(tabId);
    const url = tab.url || "";
    const low = url.toLowerCase();
    const okHost = !expectedHost || low.includes(expectedHost) || low.includes("bing.com") || low.includes("login.live.com");
    if (tab.status === "complete" && isScriptableUrl(url) && okHost) {
      await sleep(1200);
      return tab;
    }
    await sleep(450);
  }
  return await chrome.tabs.get(tabId);
}

async function navigateWorkerTab(url, extraWaitMs = 1200) {
  let host = null;
  try {
    host = new URL(url).hostname;
  } catch (_) {}
  const { tabId, justCreated } = await ensureWorkerTab(url);
  if (!justCreated) {
    await chrome.tabs.update(tabId, { url, active: false });
  }
  const tab = await waitForTabComplete(tabId, host);
  if (extraWaitMs > 0) await sleep(extraWaitMs);
  return tab;
}

async function closeWorkerTab() {
  if (workerTabId !== null) {
    try {
      await chrome.tabs.remove(workerTabId);
    } catch (_) {}
    workerTabId = null;
  }
}

async function execInTab(tabId, func, args = []) {
  const tab = await chrome.tabs.get(tabId);
  if (!isScriptableUrl(tab.url || "")) throw new Error("目标页暂不支持脚本");
  const res = await chrome.scripting.executeScript({ target: { tabId }, func, args });
  return res && res[0] ? res[0].result : null;
}

// ---------- 注入目标页的拟人操作函数 ----------
function pageSafetyCheckInPage() {
  const href = (location.href || "").toLowerCase();
  const title = (document.title || "").toLowerCase();
  const text = (document.body?.innerText || "").slice(0, 6000).toLowerCase();

  if (href.includes("login.live.com") || href.includes("login.microsoftonline.com")) {
    return { ok: false, reason: "LOGIN_REQUIRED", detail: "微软账号会话已过期，请在 Edge 重新登录。" };
  }
  const captchaWords = ["verify you are human", "are you a robot", "unusual search activity", "异常搜索活动", "请完成人机验证", "arkoselabs", "funcaptcha", "turnstile"];
  const hasCaptcha = Boolean(document.querySelector('iframe[src*="captcha"], iframe[src*="arkoselabs"], #captcha'));
  const hit = captchaWords.find((w) => text.includes(w) || title.includes(w));
  if (hasCaptcha || hit) {
    return { ok: false, reason: "CAPTCHA_OR_CHALLENGE", detail: `检测到人机验证或安全提示（${hit || "验证框"}），已自动熔断暂停，请在 Edge 手动处理。` };
  }
  for (const r of ["your account has been suspended", "temporarily restricted", "账户已暂停", "帐户已暂停", "账号已暂停"]) {
    if (text.includes(r)) {
      return { ok: false, reason: "ACCOUNT_RESTRICTED", detail: `检测到账号受限提示（${r}），已立即中止保护账号！` };
    }
  }
  return { ok: true };
}

async function humanBrowseInPage(totalDwellMs) {
  const slp = (ms) => new Promise((r) => setTimeout(r, ms));
  const rnd = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
  const endAt = Date.now() + Math.max(4000, totalDwellMs || 11000);
  await slp(rnd(1600, 3000));
  const times = rnd(2, 4);
  for (let i = 0; i < times && Date.now() < endAt - 1500; i++) {
    window.scrollBy({ top: rnd(220, 560), behavior: "smooth" });
    await slp(rnd(1600, 3600));
  }
  if (Math.random() < 0.45 && Date.now() < endAt - 1200) {
    window.scrollBy({ top: -rnd(140, 320), behavior: "smooth" });
    await slp(rnd(1000, 2200));
  }
  const rem = endAt - Date.now();
  if (rem > 300) await slp(Math.min(rem, 7000));

  const rcText = (document.querySelector("#id_rc")?.textContent || "").replace(/,/g, "").trim();
  return { bingHeaderPoints: /^\d+$/.test(rcText) ? parseInt(rcText, 10) : null };
}

function clickSkipPuzzleInPage() {
  const el =
    document.querySelector("#skipPuzzle a") ||
    Array.from(document.querySelectorAll("a, button")).find((n) => {
      const t = (n.innerText || n.getAttribute("aria-label") || "").trim();
      return t.includes("跳过拼图") || t.toLowerCase().includes("skip puzzle");
    });
  if (!el) return { clicked: false };
  el.click();
  return { clicked: true, text: (el.innerText || "").trim() };
}

async function humanTypeSearchInPage(query) {
  const slp = (ms) => new Promise((r) => setTimeout(r, ms));
  const rnd = (a, b) => Math.floor(Math.random() * (b - a + 1)) + a;
  const input = document.querySelector("#sb_form_q") || document.querySelector('input[name="q"], textarea[name="q"]');
  if (!input) return { submitted: false };

  input.focus();
  await slp(rnd(200, 420));
  const proto = input.tagName === "TEXTAREA" ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
  const setter = Object.getOwnPropertyDescriptor(proto, "value")?.set;
  const setVal = (v) => {
    if (setter) setter.call(input, v);
    else input.value = v;
    input.dispatchEvent(new Event("input", { bubbles: true }));
  };
  setVal("");
  await slp(rnd(150, 300));
  let cur = "";
  for (const ch of query) {
    cur += ch;
    setVal(cur);
    await slp(Math.random() < 0.14 ? rnd(220, 380) : rnd(60, 165));
  }
  input.dispatchEvent(new Event("change", { bubbles: true }));
  await slp(rnd(320, 750));

  const btn = document.querySelector("#search_icon, #sb_form_go, button[type='submit'], input[type='submit']");
  if (btn) {
    btn.click();
    return { submitted: true };
  }
  const form = input.closest("form") || document.querySelector("#sb_form");
  if (form) {
    form.submit();
    return { submitted: true };
  }
  return { submitted: false };
}

function pickOrganicLinkInPage() {
  const list = Array.from(document.querySelectorAll("li.b_algo h2 a[href]"))
    .map((a) => ({ href: a.href, text: (a.innerText || "").trim() }))
    .filter((x) => x.href.startsWith("https://") && !x.href.includes("bing.com/ck/") && !x.href.endsWith(".exe") && x.text.length >= 4);
  if (!list.length) return null;
  return list[Math.floor(Math.random() * Math.min(5, list.length))];
}

// ---------- 核心防风控任务流 ----------
async function waitIfPaused() {
  while (isPaused) {
    if (stopRequested) return false;
    await sleep(300);
  }
  return !stopRequested;
}

async function waitCountdown(seconds, headline, reason, st = "RUNNING") {
  const total = Math.max(1, Math.round(seconds));
  let rem = total;
  skipWaitRequested = false;
  while (rem > 0) {
    if (stopRequested) return false;
    if (skipWaitRequested) {
      skipWaitRequested = false;
      break;
    }
    if (!(await waitIfPaused())) return false;
    const mm = String(Math.floor(rem / 60)).padStart(2, "0");
    const ss = String(rem % 60).padStart(2, "0");
    await persistState({
      state: st,
      headline,
      countdownText: `${reason} · 还剩 ${mm}:${ss}`,
      countdownRemaining: rem,
      countdownTotal: total,
    });
    await sleep(1000);
    rem -= 1;
  }
  await persistState({ countdownText: "", countdownRemaining: 0, countdownTotal: 0 });
  return !stopRequested;
}

function buildVisualTasks(dailyCards, autoCards, doneSet) {
  return [...dailyCards, ...autoCards].map((c) => {
    const done = Boolean(c.completed) || doneSet.has(c.id);
    return {
      id: c.id,
      title: c.title,
      points: c.points,
      category: c.category,
      kind: c.kind,
      url: c.url,
      status: done ? "done" : c.locked ? "locked" : "pending",
    };
  });
}

async function updateTaskRowStatus(id, status) {
  state.tasks = state.tasks.map((t) => (t.id === id ? { ...t, status } : t));
  await persistState();
}

async function applyParsedData(parsed, profile, history) {
  const doneSet = new Set(getTodayRec(history).doneIds || []);
  const prevAvail = state.availablePoints;
  let gain = 0;
  const patch = {};

  if (parsed.availablePoints !== null && parsed.availablePoints !== undefined) {
    patch.availablePoints = parsed.availablePoints;
    if (prevAvail !== null && parsed.availablePoints > prevAvail) {
      gain = parsed.availablePoints - prevAvail;
    }
  }
  if (parsed.todayPoints !== null && parsed.todayPoints !== undefined) {
    patch.todayPoints = parsed.todayPoints;
  }
  if (parsed.streakDays !== null && parsed.streakDays !== undefined) {
    patch.streakDays = parsed.streakDays;
  }
  if (parsed.searchMax) {
    patch.searchMaxReported = parsed.searchMax;
    patch.searchTarget = profile.enableBingSearch ? Math.min(profile.maxSearchPointsPerDay, parsed.searchMax) : 0;
  }
  if (parsed.searchEarned !== null && parsed.searchEarned !== undefined) {
    patch.searchEarned = Math.max(state.searchEarned || 0, parsed.searchEarned);
  }
  if (Array.isArray(parsed.manualItems)) {
    patch.manualItems = parsed.manualItems.filter((m) => !doneSet.has(m.id));
  }
  if (gain > 0) triggerGainFx(gain);
  await persistState(patch);
  return gain;
}

async function runSingleCard(card, idx, total, label, history) {
  await updateTaskRowStatus(card.id, "active");
  if (card.kind === "puzzle") {
    await persistState({
      state: "RUNNING",
      headline: `${label} (${idx}/${total}) · 自动跳过拼图`,
      detail: `后台打开「${card.title}」(+${card.points} 分)，稍等 3 秒自动点击「跳过拼图」直接拿分～`,
    });
    addLog(`执行拼图跳过 [+${card.points}]：${card.title}`);
    let tab = await navigateWorkerTab(card.url, 1800);
    const safe = await execInTab(tab.id, pageSafetyCheckInPage).catch(() => ({ ok: true }));
    if (safe && !safe.ok) return { alert: safe.reason, detail: safe.detail };
    await sleep(randInt(2000, 3200));
    const skip = await execInTab(tab.id, clickSkipPuzzleInPage).catch(() => ({ clicked: false }));
    if (skip && skip.clicked) {
      await sleep(1200);
      tab = await waitForTabComplete(tab.id, "bing.com", 18000);
      await execInTab(tab.id, humanBrowseInPage, [randInt(5000, 8000)]).catch(() => sleep(5000));
    } else {
      await sleep(4000);
    }
  } else {
    await persistState({
      state: "RUNNING",
      headline: `${label} (${idx}/${total})`,
      detail: `后台打开「${card.title}」(+${card.points} 分)，模拟真人慢慢滑动浏览约 13 秒...`,
    });
    addLog(`浏览任务 [+${card.points}]：${card.title}`);
    const tab = await navigateWorkerTab(card.url, 1200);
    try {
      const safe = await execInTab(tab.id, pageSafetyCheckInPage);
      if (safe && !safe.ok) return { alert: safe.reason, detail: safe.detail };
      await execInTab(tab.id, humanBrowseInPage, [randInt(10000, 16000)]);
    } catch (_) {
      await sleep(randInt(8000, 12000));
    }
  }

  const rec = getTodayRec(history);
  if (!rec.doneIds.includes(card.id)) rec.doneIds.push(card.id);
  await saveHistory(history);
  await updateTaskRowStatus(card.id, "done");
  triggerGainFx(card.points);
  addLog(`已完成 [+${card.points}]：${card.title}`);
  return { ok: true };
}

async function runMainPipeline() {
  if (isRunning) return;
  isRunning = true;
  stopRequested = false;
  isPaused = false;
  chrome.alarms.create(KEEPALIVE_ALARM, { periodInMinutes: 0.5 });

  try {
    const cfg = await loadConfig();
    const profile = RISK_PROFILES[cfg.profileKey] || RISK_PROFILES.steady;
    const history = await loadHistory();
    addLog(`开始执行今日任务 · 当前策略：${profile.name}`);

    await persistState({
      state: "RUNNING",
      headline: "正在扫描今天的全部积分任务...",
      detail: "后台免打扰拉取每日打卡、日常浏览、拼图卡片与必应搜索进度...",
      alertMessage: "",
      stepActivities: "pending",
      stepSearch: "pending",
    });

    const parsed = await inspectRewards(true);
    if (stopRequested) return;
    if (!parsed.ok) {
      await persistState({
        state: "ALERT",
        headline: parsed.alert ? "需要你手动处理一下" : "读取积分页面失败",
        detail: parsed.message || "拉取页面失败",
        alertMessage: parsed.message || "拉取页面失败",
      });
      addLog(`中止：${parsed.message}`);
      return;
    }

    await applyParsedData(parsed, profile, history);
    const doneSet = new Set(getTodayRec(history).doneIds || []);
    const dailyCards = parsed.dailyCards || [];
    const autoCards = parsed.autoCards || [];
    const visual = buildVisualTasks(dailyCards, autoCards, doneSet);
    let dailyDone = dailyCards.filter((c) => c.completed || doneSet.has(c.id)).length;
    let earnDone = autoCards.filter((c) => c.completed || doneSet.has(c.id)).length;

    await persistState({
      tasks: visual,
      dailyDone,
      dailyTotal: dailyCards.length,
      earnDone,
      earnTotal: autoCards.length,
      stepActivities: "active",
    });
    addLog(`扫描完成：可用积分 ${state.availablePoints}，打卡 ${dailyDone}/${dailyCards.length}，日常与拼图 ${earnDone}/${autoCards.length}`);

    // 1. 每日打卡 + 日常浏览 + 拼图自动跳过
    const pendingDaily = profile.enableDailyActivities
      ? dailyCards.filter((c) => !c.completed && !c.locked && !doneSet.has(c.id))
      : [];
    const pendingAuto = profile.enableEarnCards
      ? autoCards.filter((c) => !c.completed && !c.locked && !doneSet.has(c.id))
      : [];

    for (let i = 0; i < pendingDaily.length; i++) {
      if (!(await waitIfPaused())) return;
      const r = await runSingleCard(pendingDaily[i], i + 1, pendingDaily.length, "每日打卡", history);
      if (r.alert) {
        await persistState({ state: "ALERT", headline: "触发安全保护已暂停", detail: r.detail, alertMessage: r.detail });
        return;
      }
      dailyDone += 1;
      await persistState({ dailyDone });
      if (i + 1 < pendingDaily.length) {
        const gap = randInt(profile.activityIntervalMinSec, profile.activityIntervalMaxSec);
        if (!(await waitCountdown(gap, "防风控小憩片刻～", `准备做第 ${i + 2}/${pendingDaily.length} 个每日打卡`))) return;
      }
    }

    for (let i = 0; i < pendingAuto.length; i++) {
      if (!(await waitIfPaused())) return;
      const r = await runSingleCard(pendingAuto[i], i + 1, pendingAuto.length, "日常任务", history);
      if (r.alert) {
        await persistState({ state: "ALERT", headline: "触发安全保护已暂停", detail: r.detail, alertMessage: r.detail });
        return;
      }
      earnDone += 1;
      await persistState({ earnDone });
      if ((i + 1) % 3 === 0 || i + 1 === pendingAuto.length) {
        const ref = await inspectRewards(false);
        if (ref.ok) await applyParsedData(ref, profile, history);
      }
      if (i + 1 < pendingAuto.length) {
        const gap = randInt(profile.activityIntervalMinSec, profile.activityIntervalMaxSec);
        if (!(await waitCountdown(gap, "防风控小憩片刻～", `准备做下一个日常任务 (${i + 2}/${pendingAuto.length})`))) return;
      }
    }

    await persistState({ stepActivities: "done" });

    // 2. 低频拟人必应搜索
    if (profile.enableBingSearch) {
      await persistState({ stepSearch: "active" });
      await runSearchPhase(cfg, profile, history);
      if (stopRequested || state.state === "ALERT") return;
      await persistState({ stepSearch: "done" });
    } else {
      await persistState({ stepSearch: "skipped" });
      addLog("当前为「仅打卡不搜索」模式，跳过自动搜索。");
    }

    // 3. 收尾核对与清理
    const finalRes = await inspectRewards(false);
    if (finalRes.ok) await applyParsedData(finalRes, profile, history);
    await closeWorkerTab();

    const msg = `今日任务全部完成！当前可用积分 ${state.availablePoints ?? "--"}（今日 +${state.todayPoints ?? 0}）。`;
    addLog(msg);
    await persistState({
      state: "DONE",
      headline: `今日任务全部搞定啦！（可用 ${state.availablePoints ?? "--"}）`,
      detail: "后台工作标签页已自动关闭，极其猫功成身退～",
      countdownText: "",
      countdownRemaining: 0,
      countdownTotal: 0,
    });
    notifyUser("极其猫微软积分助手 · 今日任务完成", msg);
  } catch (err) {
    const errMsg = String(err?.message || err);
    addLog(`运行异常：${errMsg}`);
    await persistState({ state: "ALERT", headline: "遇到一点小状况", detail: errMsg, alertMessage: errMsg });
  } finally {
    isRunning = false;
  }
}

async function runSearchPhase(cfg, profile, history) {
  const target = Math.min(profile.maxSearchPointsPerDay, state.searchMaxReported || 60);
  await persistState({ searchTarget: target });
  if ((state.searchEarned || 0) >= target) {
    addLog(`必应搜索已达今日目标（${state.searchEarned}/${target}），无需再搜。`);
    return;
  }

  let batchLimit = randInt(profile.batchSizeMin, profile.batchSizeMax);
  let batchDone = 0;
  let sinceVerify = 0;
  let lastVerifiedSearch = state.searchEarned || 0;
  let lastVerifiedAvail = state.availablePoints || 0;
  let noGainCount = 0;
  let cooldownCount = 0;
  let sessionCount = 0;
  const recentSet = new Set(history.recentQueries || []);

  while ((state.searchEarned || 0) < target && sessionCount < 35 && !stopRequested) {
    if (!(await waitIfPaused())) return;
    const query = await pickNaturalQuery(recentSet);
    recentSet.add(query);
    sessionCount += 1;

    await persistState({
      state: "RUNNING",
      headline: `模拟真人搜必应（${state.searchEarned}/${target} 分）`,
      detail: `第 ${sessionCount} 次：在必应逐字输入「${query}」并浏览结果...`,
    });
    addLog(`第 ${sessionCount} 次搜索：${query}`);

    const { tabId } = await ensureWorkerTab("https://www.bing.com/");
    let tab = await chrome.tabs.get(tabId);
    if (!String(tab.url || "").toLowerCase().includes("bing.com")) {
      tab = await navigateWorkerTab("https://www.bing.com/", 1200);
    }
    const preSafe = await execInTab(tab.id, pageSafetyCheckInPage).catch(() => ({ ok: true }));
    if (preSafe && !preSafe.ok) {
      await persistState({ state: "ALERT", headline: "触发安全保护已暂停", detail: preSafe.detail, alertMessage: preSafe.detail });
      return;
    }

    const typed = await execInTab(tab.id, humanTypeSearchInPage, [query]).catch(() => ({ submitted: false }));
    if (typed && typed.submitted) {
      await sleep(1000);
      tab = await waitForTabComplete(tab.id, "bing.com", 20000);
    } else {
      tab = await navigateWorkerTab(`https://www.bing.com/search?q=${encodeURIComponent(query)}&FORM=QBLH`, 1200);
    }

    const postSafe = await execInTab(tab.id, pageSafetyCheckInPage).catch(() => ({ ok: true }));
    if (postSafe && !postSafe.ok) {
      await persistState({ state: "ALERT", headline: "触发安全保护已暂停", detail: postSafe.detail, alertMessage: postSafe.detail });
      return;
    }

    const browse = await execInTab(tab.id, humanBrowseInPage, [randInt(13000, 20000)]).catch(() => ({}));

    // 约 15% 概率顺手点开一条无害自然搜索结果停留数秒
    if (cfg.allowClickOrganic && Math.random() < 0.15) {
      const picked = await execInTab(tab.id, pickOrganicLinkInPage).catch(() => null);
      if (picked && picked.href) {
        await navigateWorkerTab(picked.href, randInt(3500, 6500)).catch(() => {});
        await navigateWorkerTab("https://www.bing.com/", 1000).catch(() => {});
      }
    }

    history.recentQueries.push(query);
    getTodayRec(history).queriesToday.push(query);
    await saveHistory(history);
    await persistState({ recentQueries: [query, ...(state.recentQueries || [])].slice(0, 8) });

    batchDone += 1;
    sinceVerify += 1;

    if (typeof browse?.bingHeaderPoints === "number" && lastVerifiedAvail > 0 && browse.bingHeaderPoints > lastVerifiedAvail) {
      const diff = browse.bingHeaderPoints - lastVerifiedAvail;
      const est = Math.min(target, (state.searchEarned || 0) + diff);
      lastVerifiedAvail = browse.bingHeaderPoints;
      lastVerifiedSearch = est;
      noGainCount = 0;
      triggerGainFx(diff);
      await persistState({ availablePoints: browse.bingHeaderPoints, searchEarned: est });
      if (est >= target) break;
    }

    if (sinceVerify >= 2 || target - (state.searchEarned || 0) <= 6 || batchDone >= batchLimit) {
      sinceVerify = 0;
      const v = await inspectRewards(false);
      if (v.ok) {
        const gain = await applyParsedData(v, profile, history);
        const curAvail = state.availablePoints || 0;
        let curS = state.searchEarned || 0;
        if (curAvail > lastVerifiedAvail) {
          const delta = curAvail - lastVerifiedAvail;
          lastVerifiedAvail = curAvail;
          curS = Math.max(curS, Math.min(target, lastVerifiedSearch + delta));
          await persistState({ searchEarned: curS });
        }
        if (curS > lastVerifiedSearch || gain > 0) {
          addLog(`积分核验成功：当前搜索 ${curS}/${target} 分`);
          lastVerifiedSearch = curS;
          noGainCount = 0;
        } else {
          noGainCount += 1;
          addLog(`本轮核验暂未检测到新分（连续第 ${noGainCount} 次），可能触发 15 分钟冷却。`);
        }
      }
      if ((state.searchEarned || 0) >= target) break;

      if (noGainCount >= cfg.maxConsecutiveNoGain) {
        cooldownCount += 1;
        if (cooldownCount > cfg.maxCooldownRetriesPerDay) {
          addLog("今日冷却次数已达安全上限，提前结束搜索以保护账号。");
          break;
        }
        const coolSec = profile.cooldownWaitSec + randInt(15, 75);
        addLog(`【防风控冷却避让】自动休眠 ${Math.floor(coolSec / 60)} 分 ${coolSec % 60} 秒...`);
        noGainCount = 0;
        batchDone = 0;
        batchLimit = randInt(profile.batchSizeMin, profile.batchSizeMax);
        await persistState({ detail: "检测到微软 15 分钟搜索冷却限制，先乖乖歇一会儿再继续，保护账号不封号～" });
        if (!(await waitCountdown(coolSec, "防风控 · 避开 15 分钟冷却中", "冷却休眠结束后自动继续", "COOLING"))) return;
        continue;
      }
    }

    if (batchDone >= batchLimit) {
      batchDone = 0;
      batchLimit = randInt(profile.batchSizeMin, profile.batchSizeMax);
      const restSec = randInt(profile.batchRestMinSec, profile.batchRestMaxSec);
      addLog(`完成一小批搜索，自然休息 ${Math.floor(restSec / 60)} 分 ${restSec % 60} 秒...`);
      await persistState({ detail: "刚搜完一小批，模拟真人歇几分钟再继续搜～" });
      if (!(await waitCountdown(restSec, "防风控 · 分批自然休息中", "休息结束后自动继续", "COOLING"))) return;
    } else {
      const gap = randInt(profile.minSearchIntervalSec, profile.maxSearchIntervalSec);
      await persistState({ detail: `刚搜完「${query}」，随机等几十秒再搜下一条，模拟真人节奏。` });
      if (!(await waitCountdown(gap, `模拟真人节奏（${state.searchEarned}/${target} 分）`, "距离下一条自然搜索", "RUNNING"))) return;
    }
  }
}

async function refreshStatusNow() {
  const cfg = await loadConfig();
  const profile = RISK_PROFILES[cfg.profileKey] || RISK_PROFILES.steady;
  const history = await loadHistory();
  const parsed = await inspectRewards(true);
  if (!parsed.ok) return { ok: false, message: parsed.message };
  await applyParsedData(parsed, profile, history);
  const doneSet = new Set(getTodayRec(history).doneIds || []);
  const activeIds = new Set((state.tasks || []).filter((t) => t.status === "active").map((t) => t.id));
  const dailyCards = parsed.dailyCards || [];
  const autoCards = parsed.autoCards || [];
  const visual = buildVisualTasks(dailyCards, autoCards, doneSet).map((t) =>
    activeIds.has(t.id) && t.status !== "done" ? { ...t, status: "active" } : t
  );
  await persistState({
    tasks: visual,
    dailyDone: dailyCards.filter((c) => c.completed || doneSet.has(c.id)).length,
    dailyTotal: dailyCards.length,
    earnDone: autoCards.filter((c) => c.completed || doneSet.has(c.id)).length,
    earnTotal: autoCards.length,
  });
  addLog("已刷新最新积分与任务完成状态。");
  return { ok: true };
}

// ---------- 事件监听 ----------
chrome.action.onClicked.addListener(() => {
  openOrFocusPanelWindow();
});

chrome.windows.onRemoved.addListener((winId) => {
  if (winId === panelWindowId) panelWindowId = null;
});

chrome.tabs.onRemoved.addListener((tabId) => {
  if (tabId === workerTabId) workerTabId = null;
});

chrome.runtime.onStartup.addListener(async () => {
  const cfg = await loadConfig();
  if (cfg.autoPopupOnStartup) {
    await openOrFocusPanelWindow();
  }
  if (cfg.autoRunOnStartup) {
    setTimeout(() => runMainPipeline(), 2500);
  }
});

chrome.runtime.onInstalled.addListener(async (details) => {
  chrome.alarms.create(KEEPALIVE_ALARM, { periodInMinutes: 0.5 });
  if (details.reason === "install") {
    await openOrFocusPanelWindow();
  }
});

chrome.alarms.onAlarm.addListener((alarm) => {
  if (alarm.name === KEEPALIVE_ALARM) {
    // 保活 Service Worker
  }
});

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  (async () => {
    const type = msg?.type;
    if (type === "get_all") {
      const cfg = await loadConfig();
      sendResponse({ ok: true, state, config: cfg, logs: logs.slice(-80) });
      return;
    }
    if (type === "start") {
      runMainPipeline();
      sendResponse({ ok: true });
      return;
    }
    if (type === "restart") {
      stopRequested = true;
      isPaused = false;
      skipWaitRequested = true;
      setTimeout(() => runMainPipeline(), 600);
      sendResponse({ ok: true });
      return;
    }
    if (type === "pause_toggle") {
      if (!isRunning) {
        runMainPipeline();
        sendResponse({ ok: true, paused: false });
        return;
      }
      isPaused = !isPaused;
      await persistState({
        state: isPaused ? "PAUSED" : "RUNNING",
        headline: isPaused ? "已暂停任务" : "极其猫继续干活啦～",
        detail: isPaused ? "先歇一会儿，点「继续运行」随时恢复。" : "正在恢复当前积分任务...",
      });
      sendResponse({ ok: true, paused: isPaused });
      return;
    }
    if (type === "stop") {
      stopRequested = true;
      isPaused = false;
      skipWaitRequested = true;
      await closeWorkerTab();
      await persistState({
        state: "STOPPED",
        headline: "已手动停止",
        detail: "点「开始运行」随时继续完成今日剩余积分。",
        countdownText: "",
        countdownRemaining: 0,
        countdownTotal: 0,
      });
      sendResponse({ ok: true });
      return;
    }
    if (type === "skip_wait") {
      skipWaitRequested = true;
      sendResponse({ ok: true });
      return;
    }
    if (type === "refresh") {
      const r = await refreshStatusNow();
      sendResponse(r);
      return;
    }
    if (type === "update_config") {
      const next = await saveConfig(msg.patch || {});
      addLog(`已更新设置：策略=${RISK_PROFILES[next.profileKey]?.name || next.profileKey}`);
      sendResponse({ ok: true, config: next });
      return;
    }
    if (type === "open_manual") {
      await chrome.tabs.create({ url: msg.url || "https://rewards.bing.com/earn", active: true });
      setTimeout(() => refreshStatusNow(), 7000);
      setTimeout(() => refreshStatusNow(), 18000);
      sendResponse({ ok: true });
      return;
    }
    if (type === "dismiss_manual") {
      const history = await loadHistory();
      const rec = getTodayRec(history);
      if (msg.id && !rec.doneIds.includes(msg.id)) rec.doneIds.push(msg.id);
      await saveHistory(history);
      await persistState({ manualItems: (state.manualItems || []).filter((m) => m.id !== msg.id) });
      sendResponse({ ok: true });
      return;
    }
    sendResponse({ ok: false });
  })();
  return true;
});

