/**
 * 哈基米积分助手 - Microsoft Rewards 精准解析器（纯 JS ES Module）
 *
 * 通过解析扩展后台带 Edge 登录态 Cookie 拉取的 SSR HTML（dashboard / earn / flyout），
 * 零 DOM 注入规避 Edge 对 rewards.bing.com 的脚本限制，100% 精准识别：
 * - 可用总积分、今日已赚、连续打卡、必应搜索进度
 * - 每日打卡（3/3 完整）、日常浏览任务（+5/+15）、拼图自动跳过任务（+100/+5）
 * - 严格拦截抽奖、兑换、软件自动下载等危险推广链接
 */

const BLOCKED_URL_MARKERS = [
  "autodownload",
  "/redeem",
  "/sweeps",
  "win-promo",
  "apps/wallpaper",
  "microsoftstore.com",
  "discord",
  "referandearn",
];

function decodeHtmlEntities(str) {
  if (!str) return "";
  return str
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&nbsp;/g, " ");
}

function stripTagsToText(rawHtml) {
  if (!rawHtml) return "";
  return decodeHtmlEntities(
    rawHtml
      .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, " ")
      .replace(/<[^>]+>/g, "\n")
  )
    .replace(/[ \t]+/g, " ")
    .replace(/\n{2,}/g, "\n");
}

function unescapeNextPayload(rawHtml) {
  if (!rawHtml) return "";
  return rawHtml
    .replace(/\\"/g, '"')
    .replace(/\\u0026/g, "&")
    .replace(/\\u003c/g, "<")
    .replace(/\\u003e/g, ">");
}

export function classifyOfferUrl(url) {
  const low = (url || "").toLowerCase();
  if (BLOCKED_URL_MARKERS.some((b) => low.includes(b))) return "blocked";
  if (low.includes("bing.com/spotlight/imagepuzzle")) return "puzzle";
  if (low.includes("homepage%20quiz") || low.includes("homepage+quiz") || low.includes("/earn/quest/")) {
    return "manual";
  }
  if (
    low.startsWith("https://www.bing.com/search") ||
    low.startsWith("https://cn.bing.com/search") ||
    low.startsWith("https://microsoftedgewelcome.microsoft.com/")
  ) {
    return "browse";
  }
  return "blocked";
}

function extractNextOfferObjects(rawHtml) {
  if (!rawHtml) return [];
  const text = unescapeNextPayload(rawHtml);
  const results = [];
  const seen = new Set();
  const re = /\{[^{}]*"(?:destination|destinationUrl)"\s*:\s*"https:\/\/[^"]+"[^{}]*\}/g;

  let m;
  while ((m = re.exec(text)) !== null) {
    const chunk = m[0];
    if (!chunk.includes('"points"') || !chunk.includes('"title"')) continue;
    let obj;
    try {
      obj = JSON.parse(chunk.replace(/"\$undefined"/g, "null"));
    } catch (_) {
      continue;
    }
    if (!obj || typeof obj !== "object") continue;

    const url = decodeHtmlEntities(String(obj.destination || obj.destinationUrl || "").trim());
    const title = String(obj.title || "").trim();
    const pts = Number(obj.points || 0);
    if (!url || !title || !Number.isFinite(pts) || pts <= 0) continue;

    const offerId = String(obj.offerId || obj.name || url);
    const key = `${offerId}|${url}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const isCompleted = obj.isCompleted === true;
    const isLocked = obj.isLocked === true && obj.isUnlocked !== true;

    results.push({
      offerId,
      title: title.slice(0, 48),
      points: Math.round(pts),
      url,
      completed: isCompleted,
      locked: isLocked,
    });
  }
  return results;
}

function extractAnchorsFallback(rawHtml) {
  if (!rawHtml) return [];
  const anchors = [];
  const re = /<a\b([^>]*?)href=["']([^"']+)["']([^>]*)>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = re.exec(rawHtml)) !== null) {
    const attrs = `${m[1]} ${m[3]}`.toLowerCase();
    const href = decodeHtmlEntities(m[2].trim());
    const inner = m[4] || "";
    const text = stripTagsToText(inner).replace(/\s+/g, " ").trim();
    const innerLow = inner.toLowerCase();
    const completed =
      attrs.includes("已完成") ||
      attrs.includes("completed") ||
      text.includes("已完成") ||
      innerLow.includes("checkmark") ||
      innerLow.includes("#107c10") ||
      innerLow.includes("#13a10e") ||
      innerLow.includes("icon-complete");
    anchors.push({ href, text, completed });
  }
  return anchors;
}

function cleanCardTitle(text) {
  const t = String(text || "")
    .replace(/\+\s*\d+[\s\S]*$/, "")
    .replace(/\s+/g, " ")
    .trim();
  return t.slice(0, 48) || "积分活动";
}

function checkHtmlSafety(rawHtml, sourceName) {
  if (!rawHtml) return null;
  const low = rawHtml.slice(0, 16000).toLowerCase();
  const textLow = stripTagsToText(rawHtml.slice(0, 30000)).toLowerCase();
  if (
    low.includes("login.live.com") &&
    !low.includes("rewards.bing.com") &&
    (textLow.includes("登录你的 microsoft 账户") || textLow.includes("sign in to your microsoft account"))
  ) {
    return {
      alert: "LOGIN_REQUIRED",
      message: `检测到微软账号未登录（${sourceName}），请先在 Edge 登录 Microsoft Rewards。`,
    };
  }
  for (const marker of [
    "account has been suspended",
    "account has been temporarily restricted",
    "账户已暂停",
    "帐户已暂停",
    "账号已暂停",
  ]) {
    if (textLow.includes(marker)) {
      return {
        alert: "ACCOUNT_RESTRICTED",
        message: `检测到账号受限提示（${marker}），已自动暂停所有任务以保护账号！`,
      };
    }
  }
  return null;
}

/**
 * 综合解析 dashboard / earn / flyout 三份 HTML。
 */
export function parseRewardsBundle({ dashboardHtml = "", earnHtml = "", flyoutHtml = "" }) {
  for (const [name, body] of [
    ["dashboard", dashboardHtml],
    ["earn", earnHtml],
    ["flyout", flyoutHtml],
  ]) {
    const safety = checkHtmlSafety(body, name);
    if (safety) return { ok: false, ...safety };
  }

  const dashText = stripTagsToText(dashboardHtml);
  const earnText = stripTagsToText(earnHtml);
  const flyoutText = stripTagsToText(flyoutHtml);
  const dashUnesc = unescapeNextPayload(dashboardHtml);
  const earnUnesc = unescapeNextPayload(earnHtml);

  // 1. 可用总积分
  let availablePoints = null;
  for (const [re, src] of [
    [/"availablePoints"\s*:\s*(\d+)/, earnUnesc],
    [/"availablePoints"\s*:\s*(\d+)/, dashUnesc],
    [/"balance"\s*:\s*(\d+)/, earnUnesc],
    [/可用积分\s*([\d,]+)/, dashText],
    [/可用积分\s*([\d,]+)/, earnText],
  ]) {
    const m = src.match(re);
    if (m) {
      availablePoints = parseInt(m[1].replace(/,/g, ""), 10);
      break;
    }
  }

  // 2. 今日积分
  let todayPoints = null;
  for (const [re, src] of [
    [/"todayPoints"\s*:\s*(\d+)/, earnUnesc],
    [/"earnedToday"\s*:\s*(\d+)/, earnUnesc],
    [/今日积分\s*([\d,]+)/, earnText],
  ]) {
    const m = src.match(re);
    if (m) {
      todayPoints = parseInt(m[1].replace(/,/g, ""), 10);
      break;
    }
  }

  // 3. 连续打卡天数
  let streakDays = null;
  for (const src of [dashText, earnText]) {
    const m = src.match(/每日连续打卡\s*(\d+)/);
    if (m) {
      streakDays = parseInt(m[1], 10);
      break;
    }
  }

  // 4. 必应搜索进度
  let searchEarned = null;
  let searchMax = 60;
  for (const [re, src] of [
    [/必应搜索\s*(\d+)\s*\/\s*(\d+)/, earnText],
    [/收入\s*(\d+)\s*\/\s*(\d+)/, flyoutText],
    [/搜索\s*(\d+)\s*\/\s*(\d+)/, flyoutText],
    [/(\d+)\s*\/\s*(60|90|150)\b/, flyoutText],
  ]) {
    const m = src.match(re);
    if (m) {
      searchEarned = parseInt(m[1], 10);
      searchMax = parseInt(m[2], 10);
      break;
    }
  }

  // 5. 每日打卡（JSON 主轨 + <a> 增量补齐，保证 3/3 完整）
  const dailyCards = [];
  const seenDailyUrls = new Set();

  for (const obj of extractNextOfferObjects(dashboardHtml)) {
    const low = obj.url.toLowerCase();
    const idLow = obj.offerId.toLowerCase();
    if (!low.includes("dailyset") && !idLow.includes("dailyset") && !low.includes("rnoreward=1")) continue;
    const kind = classifyOfferUrl(obj.url);
    if (kind === "blocked") continue;
    if (seenDailyUrls.has(obj.url)) continue;
    seenDailyUrls.add(obj.url);
    dailyCards.push({
      id: `daily:${obj.offerId}`,
      category: "每日打卡",
      kind,
      title: obj.title,
      points: obj.points,
      url: obj.url,
      completed: obj.completed,
      locked: obj.locked,
    });
  }

  for (const a of [...extractAnchorsFallback(dashboardHtml), ...extractAnchorsFallback(flyoutHtml)]) {
    const low = a.href.toLowerCase();
    if (!low.includes("bing.com/search")) continue;
    if (!low.includes("dailyset") && !low.includes("rnoreward=1")) continue;
    const norm = low.split("&filters=")[0];
    const dup = Array.from(seenDailyUrls).some((u) => u.toLowerCase().split("&filters=")[0] === norm);
    if (dup) continue;
    seenDailyUrls.add(a.href);
    const pm = a.text.match(/\+\s*(\d+)/);
    dailyCards.push({
      id: `daily:${norm}`,
      category: "每日打卡",
      kind: "browse",
      title: cleanCardTitle(a.text),
      points: pm ? parseInt(pm[1], 10) : 10,
      url: a.href,
      completed: a.completed,
      locked: false,
    });
  }

  // 6. 日常安全浏览 + 拼图自动跳过任务
  const autoCards = [];
  const manualItems = [];
  const seenEarn = new Set(seenDailyUrls);

  for (const obj of extractNextOfferObjects(earnHtml)) {
    const key = `${obj.offerId}|${obj.url}`;
    if (seenDailyUrls.has(obj.url) || seenEarn.has(key)) continue;
    if (obj.url.toLowerCase().includes("dailyset") || obj.offerId.toLowerCase().includes("dailyset")) continue;
    const kind = classifyOfferUrl(obj.url);
    if (kind === "blocked") continue;
    seenEarn.add(key);

    if (kind === "manual") {
      if (!obj.completed && !obj.locked) {
        manualItems.push({
          id: `manual:${obj.offerId}`,
          title: obj.title,
          points: obj.points,
          url: obj.url,
          kind: obj.url.toLowerCase().includes("/earn/quest/") ? "系列组合任务" : "互动问答",
        });
      }
      continue;
    }

    autoCards.push({
      id: `earn:${obj.offerId}`,
      category: kind === "puzzle" ? "拼图(自动跳过)" : "日常浏览",
      kind,
      title: obj.title,
      points: obj.points,
      url: obj.url,
      completed: obj.completed,
      locked: obj.locked,
    });
  }

  if (autoCards.length === 0) {
    for (const a of extractAnchorsFallback(earnHtml)) {
      if (!a.href || seenEarn.has(a.href)) continue;
      const pm = a.text.match(/\+\s*(\d+)/);
      if (!pm) continue;
      const kind = classifyOfferUrl(a.href);
      if (kind === "blocked") continue;
      seenEarn.add(a.href);
      const pts = parseInt(pm[1], 10);
      const title = cleanCardTitle(a.text);
      if (kind === "manual") {
        if (!a.completed) {
          manualItems.push({ id: `manual:${a.href}`, title, points: pts, url: a.href, kind: "互动问答" });
        }
        continue;
      }
      autoCards.push({
        id: `earn:${a.href}`,
        category: kind === "puzzle" ? "拼图(自动跳过)" : "日常浏览",
        kind,
        title,
        points: pts,
        url: a.href,
        completed: a.completed,
        locked: false,
      });
    }
  }

  if (/签到:\s*0\s*\/\s*1/.test(earnText) || /签到:\s*0\s*\/\s*1/.test(dashText)) {
    manualItems.push({
      id: "manual:mobile_checkin",
      title: "手机端必应 App 每日签到",
      points: 5,
      url: "https://rewards.bing.com/earn",
      kind: "移动端任务",
    });
  }

  return {
    ok: true,
    availablePoints,
    todayPoints,
    streakDays,
    searchEarned,
    searchMax,
    dailyCards,
    autoCards,
    manualItems,
  };
}

