/**
 * 轻量获取必应公开搜索联想词，使每日搜索更具时效与自然多样性。
 * @param {string} seed
 * @returns {Promise<string[]>}
 */
export async function fetchBingSuggestions(seed) {
  try {
    const url = `https://api.bing.com/osjson.aspx?query=${encodeURIComponent(seed)}&language=zh-CN`;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 4000);
    const resp = await fetch(url, { signal: ctrl.signal });
    clearTimeout(timer);
    if (!resp.ok) return [];
    const data = await resp.json();
    if (Array.isArray(data) && Array.isArray(data[1])) {
      return data[1]
        .map((x) => String(x || "").trim())
        .filter((s) => s.length >= 3 && s.length <= 26);
    }
  } catch (_) {}
  return [];
}

/**
 * 从自然词库 + 时令主题 + 实时联想中挑选一个近期未搜过的自然中文搜索词。
 * @param {Set<string>} recentSet
 * @returns {Promise<string>}
 */
export async function pickNaturalQuery(recentSet) {
  const month = new Date().getMonth() + 1;
  const pool = [...BASE_NATURAL_QUERIES, ...(SEASONAL_TOPICS[month] || [])];

  // 约 40% 概率混入几条当日必应自然联想词
  if (Math.random() < 0.4) {
    const seeds = [`${month}月旅游`, "家常菜做法", "高分电影推荐", "科普知识", "数码评测"];
    const seed = seeds[Math.floor(Math.random() * seeds.length)];
    const dyn = await fetchBingSuggestions(seed);
    if (dyn.length > 0) {
      pool.unshift(...dyn.slice(0, 6));
    }
  }

  // Fisher-Yates 洗牌
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }

  for (const q of pool) {
    if (!recentSet.has(q)) return q;
  }

  const suffixes = [" 攻略", " 推荐", " 怎么选", " 注意事项"];
  const base = pool[Math.floor(Math.random() * pool.length)] || "家常菜推荐";
  return `${base}${suffixes[Math.floor(Math.random() * suffixes.length)]}`;
}

