/**
 * 哈基米积分助手（纯 Edge 插件版） - 独立小窗看板控制脚本
 */

const $ = (id) => document.getElementById(id);
let lastGainSeq = 0;
let toastTimer = null;
let userToggledTasks = false;
let tasksCollapsed = false;
let currentConfig = {};

function showToast(msg) {
  const el = $("toast");
  el.textContent = msg;
  el.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove("show"), 2200);
}

function escapeHtml(s) {
  return String(s || "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function sendMsg(payload) {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage(payload, (resp) => resolve(resp || { ok: false }));
  });
}

function applyCollapse() {
  $("taskList").classList.toggle("collapsed", tasksCollapsed);
  $("btnToggleTasks").textContent = tasksCollapsed ? "展开明细 ▾" : "收起 ▴";
}

function render(st, cfg, logLines) {
  if (!st) return;
  if (cfg) currentConfig = cfg;

  const pillMap = {
    IDLE: ["准备就绪", "muted"],
    RUNNING: ["正在运行", "running"],
    COOLING: ["防风控休息", "cooling"],
    PAUSED: ["已暂停", "muted"],
    DONE: ["今日已完成", "done"],
    ALERT: ["需人工处理", "alert"],
    STOPPED: ["已停止", "muted"],
  };
  const [pText, pCls] = pillMap[st.state] || ["运行中", "running"];
  $("pillText").textContent = pText;
  $("statusPill").className = `pill ${pCls}`;

  $("headline").textContent = st.headline || "极其猫准备就绪";
  $("detail").textContent = st.detail || "";

  if (st.countdownRemaining > 0 && st.countdownTotal > 0) {
    $("cdBox").classList.add("show");
    $("cdText").textContent = st.countdownText || "";
    const pct = Math.max(2, Math.min(100, Math.round((st.countdownRemaining / st.countdownTotal) * 100)));
    $("cdFill").style.width = `${pct}%`;
  } else {
    $("cdBox").classList.remove("show");
  }

  if (st.lastGainSeq && st.lastGainSeq !== lastGainSeq && st.lastGainPoints > 0) {
    lastGainSeq = st.lastGainSeq;
    const pop = $("gainPop");
    pop.textContent = `+${st.lastGainPoints} 分`;
    pop.classList.remove("animate");
    void pop.offsetWidth;
    pop.classList.add("animate");
  }

  if (st.availablePoints !== null && st.availablePoints !== undefined) {
    $("statAvail").textContent = Number(st.availablePoints).toLocaleString();
  }
  if (st.todayPoints !== null && st.todayPoints !== undefined) {
    $("statToday").textContent = `+${st.todayPoints}`;
  }
  const sEarned = st.searchEarned || 0;
  const sTarget = st.searchTarget ?? 60;
  $("statSearch").textContent = `${sEarned} / ${sTarget}`;

  const tasks = st.tasks || [];
  const totalT = tasks.length;
  const doneT = tasks.filter((t) => t.status === "done").length;
  if (totalT > 0) {
    const pct = Math.round((doneT / totalT) * 100);
    const allDone = doneT >= totalT;
    $("taskSummary").textContent = allDone
      ? `✓ 全部完成 ${doneT}/${totalT}（打卡 ${st.dailyDone || 0}/${st.dailyTotal || 0}）`
      : `已完成 ${doneT}/${totalT} · 打卡 ${st.dailyDone || 0}/${st.dailyTotal || 0}`;
    $("taskSummary").className = `panel-sub${allDone ? " done" : ""}`;
    $("cardsBarFill").style.width = `${pct}%`;
    $("cardsBarFill").classList.toggle("full", allDone);
    $("btnToggleTasks").style.display = "inline-block";

    if (!userToggledTasks) tasksCollapsed = allDone && st.stepActivities === "done";
    applyCollapse();

    const iconMap = { done: "✓", active: "▶", pending: "○", locked: "🔒" };
    const stateMap = { done: "已完成", active: "正在执行...", pending: "排队中", locked: "未解锁" };
    $("taskList").innerHTML = tasks
      .map(
        (t) => `
      <div class="task-row ${t.status}">
        <span class="task-icon ${t.status}">${iconMap[t.status] || "○"}</span>
        <div class="task-info">
          <div class="task-name">${escapeHtml(t.title)}</div>
          <div class="task-meta">${escapeHtml(t.category)} · ${stateMap[t.status] || ""}</div>
        </div>
        <span class="task-pts">+${t.points}</span>
      </div>`
      )
      .join("");
  }

  const sPct = sTarget > 0 ? Math.min(100, Math.round((sEarned / sTarget) * 100)) : 100;
  const sFull = sTarget === 0 || sEarned >= sTarget;
  if (st.stepSearch === "skipped" || sTarget === 0) {
    $("searchSummary").textContent = "已跳过（仅打卡模式）";
    $("searchBarFill").style.width = "0%";
    $("searchMeta").textContent = "当前模式不自动刷搜索。";
  } else {
    $("searchSummary").textContent = `${sEarned} / ${sTarget} 分 (${sPct}%)`;
    $("searchSummary").className = `panel-sub${sFull ? " done" : ""}`;
    $("searchBarFill").style.width = `${sPct}%`;
    $("searchBarFill").classList.toggle("full", sFull);
    const streak = st.streakDays ? `已连续打卡 ${st.streakDays} 天` : "";
    const qs = st.recentQueries || [];
    $("searchMeta").textContent = sFull
      ? `✓ 今日搜索目标已达标！${streak ? " · " + streak : ""}`
      : qs.length > 0
      ? `最近自然搜索词${streak ? " · " + streak : ""}：`
      : `等待进入低频拟人搜索${streak ? " · " + streak : ""}...`;
    $("queryChips").innerHTML = qs.map((q) => `<span class="chip">${escapeHtml(q)}</span>`).join("");
  }

  const manuals = st.manualItems || [];
  if (manuals.length > 0) {
    $("manualPanel").style.display = "flex";
    $("manualList").innerHTML = manuals
      .map(
        (m) => `
      <div class="manual-row">
        <div class="task-info">
          <div class="task-name">${escapeHtml(m.title)} <span style="color:var(--amber)">+${m.points || 0}</span></div>
          <div class="task-meta">${escapeHtml(m.kind || "需手动")} · 做完自动刷新</div>
        </div>
        <div class="manual-actions">
          <button class="mini-btn" data-open-url="${escapeHtml(m.url)}">去完成</button>
          <button class="mini-btn ok" data-dismiss-id="${escapeHtml(m.id)}">✓ 已做</button>
        </div>
      </div>`
      )
      .join("");
  } else {
    $("manualPanel").style.display = "none";
  }

  const primary = $("btnPrimary");
  if (["DONE", "STOPPED", "ALERT", "IDLE"].includes(st.state)) primary.textContent = "开始运行";
  else if (st.state === "PAUSED") primary.textContent = "继续运行";
  else primary.textContent = "暂停";

  const activeKey = currentConfig.profileKey || "steady";
  document.querySelectorAll("#modeSeg button").forEach((b) => {
    b.classList.toggle("active", b.dataset.key === activeKey);
  });

  const autoOn = Boolean(currentConfig.autoRunOnStartup);
  $("btnAutoRun").classList.toggle("on", autoOn);
  $("btnAutoRun").textContent = autoOn ? "✓ 启动自跑" : "○ 启动自跑";

  if (Array.isArray(logLines) && logLines.length > 0) {
    $("logContent").textContent = logLines.join("\n");
  }
}

async function syncFromBackground() {
  const resp = await sendMsg({ type: "get_all" });
  if (resp && resp.ok) render(resp.state, resp.config, resp.logs);
}

// 实时监听 storage 变化，实现毫秒级零延迟状态反馈
chrome.storage.onChanged.addListener((changes) => {
  if (changes.hakimi_state_v2?.newValue) {
    const { state: st, logs: lg } = changes.hakimi_state_v2.newValue;
    render(st, currentConfig, lg);
  }
  if (changes.hakimi_config_v2?.newValue) {
    currentConfig = changes.hakimi_config_v2.newValue;
  }
});

$("manualList").addEventListener("click", async (e) => {
  const openBtn = e.target.closest("[data-open-url]");
  if (openBtn) {
    await sendMsg({ type: "open_manual", url: openBtn.getAttribute("data-open-url") });
    showToast("已在新标签页打开，做完几秒内自动刷新");
    return;
  }
  const doneBtn = e.target.closest("[data-dismiss-id]");
  if (doneBtn) {
    await sendMsg({ type: "dismiss_manual", id: doneBtn.getAttribute("data-dismiss-id") });
    showToast("已标记为今日已做");
    syncFromBackground();
  }
});

$("btnToggleTasks").addEventListener("click", () => {
  userToggledTasks = true;
  tasksCollapsed = !tasksCollapsed;
  applyCollapse();
});
$("btnRefresh").addEventListener("click", async () => {
  showToast("正在刷新最新积分与任务状态...");
  await sendMsg({ type: "refresh" });
  syncFromBackground();
});
$("btnManualRefresh").addEventListener("click", async () => {
  showToast("正在核验完成状态...");
  await sendMsg({ type: "refresh" });
  syncFromBackground();
});
$("btnPrimary").addEventListener("click", async () => {
  if ($("btnPrimary").textContent === "开始运行") {
    await sendMsg({ type: "start" });
    showToast("极其猫开始干活啦～");
  } else {
    const r = await sendMsg({ type: "pause_toggle" });
    showToast(r.paused ? "已暂停任务" : "已继续执行");
  }
  syncFromBackground();
});
$("btnRestart").addEventListener("click", async () => {
  userToggledTasks = false;
  await sendMsg({ type: "restart" });
  showToast("正在重新扫描并执行今日任务");
});
$("btnStop").addEventListener("click", async () => {
  await sendMsg({ type: "stop" });
  showToast("已停止任务");
});
$("btnSkipWait").addEventListener("click", async () => {
  await sendMsg({ type: "skip_wait" });
  showToast("已跳过本次等待");
});
$("btnAutoRun").addEventListener("click", async () => {
  const want = !currentConfig.autoRunOnStartup;
  const r = await sendMsg({ type: "update_config", patch: { autoRunOnStartup: want, autoPopupOnStartup: want } });
  if (r.ok) currentConfig = r.config;
  showToast(want ? "已开启：打开 Edge 自动弹出并运行" : "已关闭启动自动运行");
  syncFromBackground();
});
document.querySelectorAll("#modeSeg button").forEach((b) => {
  b.addEventListener("click", async () => {
    const r = await sendMsg({ type: "update_config", patch: { profileKey: b.dataset.key } });
    if (r.ok) currentConfig = r.config;
    showToast("已切换风控模式，点「重新运行」立即生效");
    syncFromBackground();
  });
});
$("btnLogs").addEventListener("click", () => $("logDrawer").classList.add("show"));
$("btnCloseLogs").addEventListener("click", () => $("logDrawer").classList.remove("show"));

syncFromBackground();

