const _drawImage = CanvasRenderingContext2D.prototype.drawImage;
(function() {
	'use strict';
	let MF =
		'#MF_fixed{position:fixed;top:50%;transform:translateY(-50%);right:58px;gap:10px;flex-direction:column;z-index:2147483647;display:flex}';
	MF +=
		'.MF_box{padding:10px;cursor:pointer;border-color:rgb(0,102,255);border-radius:5px;background-color:white;color:rgb(0,102,255);}.MF_active{color: green}#MF_k_page_no,#MF_k_page_size{color: red;}';
	const prefix = "MF_";

	function safeDrawImage(ctx, ...args) {
	        return _drawImage.apply(ctx, args);
	    }

	const originalLog = console.log;
	Object.defineProperty(console, 'log', {
		get: () => originalLog,
		set: () => {}
	});

	const ctxProto = CanvasRenderingContext2D.prototype;
	const originalDrawImage = ctxProto.drawImage;
	Object.defineProperty(ctxProto, 'drawImage', {
		get: () => originalDrawImage,
		set: () => {}
	});

	const originalFont = Object.getOwnPropertyDescriptor(ctxProto, 'font');
	Object.defineProperty(ctxProto, 'font', {
		get: function() {
			return originalFont.get.call(this);
		},
		set: function(value) {
			if (value.includes('no-real-font-123')) {
				value = '11pt Arial';
			}
			return originalFont.set.call(this, value);
		}
	});

	const originalToDataURL = HTMLCanvasElement.prototype.toDataURL;
	Object.defineProperty(HTMLCanvasElement.prototype, 'toDataURL', {
		get: () => originalToDataURL,
		set: () => {}
	});


	class Box {
		id = ""; // id
		label = ""; // 按钮文本
		title = "";
		fun = ""; // 执行方法
		constructor(id, label, fun) {
			this.id = id;
			this.label = label;
			this.fun = fun;
		}

		setTitle(title) {
			this.title = title;
			return this;
		}
	}

	class Utility {
		debug = true;

		/**
		 * 添加 css 样式
		 * @param e 节点
		 * @param data JSON 格式样式
		 */
		style(e, data) {
			Object.keys(data).forEach(key => {
				e.style[key] = data[key]
			})
		}

		attr(e, key, val) {
			if (!val) {
				return e.getAttribute(key);
			} else {
				e.setAttribute(key, val);
			}

		}

		/**
		 *  追加样式
		 * @param css  格式样式
		 */
		appendStyle(css) {
			let style = this.createEl('', 'style');
			style.textContent = css;
			style.type = 'text/css';
			let dom = document.head || document.documentElement;
			dom.appendChild(style);
		}

		/**
		 * @description 创建 dom
		 * @param id 必填
		 * @param elType
		 * @param data
		 */
		createEl(id, elType, data) {
			const el = document.createElement(elType);
			el.id = id || '';
			if (data) {
				this.style(el, data);
			}
			return el;
		}

		query(el) {
			return document.querySelector(el);
		}

		queryAll(el) {
			return document.querySelectorAll(el);
		}

		update(el, text) {
			const elNode = this.query(el);
			if (!elNode) {
				console.log('节点不存在');
			} else {
				elNode.innerHTML = text;
			}
		}

		/**
		 * 进度
		 * @param current 当前数量 -1预览结束
		 * @param total 总数量
		 * @param content 内容
		 */
		preview(current, total, content) {
			return new Promise(async (resolve, reject) => {
				if (current === -1) {
					this.update('#' + prefix + 'text', content ? content : "已完成");
				} else {
					let p = (current / total) * 100;
					let ps = p.toFixed(0) > 100 ? 100 : p.toFixed(0);
					console.log('当前进度', ps)
					this.update('#' + prefix + 'text', '进度' + ps + '%');
					await this.sleep(500);
					resolve();
				}
			})

		}

		preText(content) {
			this.update('#' + prefix + 'text', content);
		}

		gui(boxs) {
			const box = this.createEl(prefix + "fixed", 'div');
			for (let x in boxs) {
				let item = boxs[x];
				if (!item.id) continue;
				let el = this.createEl(prefix + item.id, 'button');
				if (item.title) {
					el.title = item.title;
				}
				el.append(new Text(item.label));
				if (x === '0') {
					el.classList = prefix + 'box ' + prefix + "active";
				} else {
					el.className = prefix + "box";
				}
				if (item.fun) {
					el.addEventListener('click', () => {
						eval(item.fun)
					});
				}
				if (item.id === 'k_page_no') {
					this.attr(el, 'contenteditable', true)
				}
				if (item.id === 'k_speed') {
					this.attr(el, 'contenteditable', true)
				}
				if (item.id === 'k_page_size') {
					this.attr(el, 'contenteditable', true)
				}
				box.append(el);
			}
			document.body.append(box);
		}

		sleep(ms) {
			return new Promise(resolve => setTimeout(resolve, ms));
		}

		log(msg) {
			if (this.debug) {
				console.log(msg);
			}
		}

		logt(msg) {
			if (this.debug) {
				console.table(msg);
			}
		}
	}

	const u = new Utility();
	u.appendStyle(MF);


	const btns = [
		new Box('text', '状态 0 %'),
		new Box('k_speed', '2-5').setTitle('每页预览时间，默认2-5秒直接随机时间'),
		new Box('k_page_no', '1').setTitle('指定页码，从第几页开始'),
		new Box('k_page_size', '100').setTitle('指定每次下载多少页面'), ,
		new Box('handleStart', '开始执行', 'handleLoadPage()'),
		new Box('handleClean', '结束执行', 'handleClean()'),
		new Box('start', '继续预览', 'autoPreview()'),
		new Box('stop', '停止预览', 'stopPreview()'),
		new Box('pdf', '下载PDF', 'download()')
	]

	const domain = {
		wqxuetang: 'wqxuetang.com',
		scau: "lib--scau-wqxuetang-com-s.vpn.scau.edu.cn",
		nlibvpn: 'nlibvpn.bit.edu.cn',
		xwfw: 'xwfw.hut.edu.cn',
		ebook: 'ebook.hep.com.cn',
		zjjd: 'www.zjjd.cn',
		keledge: 'www.keledge.com',
		elib: 'www.elib.link',
		xianxiao: 'xianxiao.ssap.com.cn',
		sklibEdu: 'www-sklib-cn-443.web.bisu.edu.cn',
		ersp: 'ersp.lib.whu.edu.cn',
		cmpkgs: 'dcd.cmpkgs.com',
		zslib: 'sso.zslib.cn',
		sklib: 'www.sklib.cn',
		cxstar: 'www.cxstar.com',
		libresource: 'libresource.bit.edu.cn',
		ydzhy: 'yd.51zhy.cn',
	};
	const {
		host,
		href,
		origin
	} = window.location;
	const jsPDF = jspdf.jsPDF;

	const doc = new jsPDF({
		orientation: 'p',
		unit: 'px',
		compress: true,
	});
