	/**
	 * 判断 dom 是否在可视范围内
	 */
	const isVisible = (el) => {
		const rect = el.getBoundingClientRect();
		const height = rect.height + 10; // 误差
		const top = rect.top - 10; // 
		const bottom = rect.bottom; // 
		if (top <= 0 && top >= -height) {
			return true;
		} else if (bottom >= 0 && bottom <= height) {
			return true;
		} else {
			return false;
		}
	}
