  function gmFetchText(url) {
    return new Promise((resolve) => {
      GM_xmlhttpRequest({
        method: "GET",
        url,
        timeout: 20000,
        onload: (resp) => resolve({ ok: resp.status >= 200 && resp.status < 400, finalUrl: resp.finalUrl || url, text: resp.responseText || "" }),
        onerror: () => resolve({ ok: false, finalUrl: url, text: "" }),
        ontimeout: () => resolve({ ok: false, finalUrl: url, text: "" }),
      });
    });
  }

  function decodeEntities(s) {
    return String(s || "")
      .replace(/&amp;/g, "&")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">");
  }

  function stripTags(h) {
    return decodeEntities(String(h || "").replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, " ").replace(/<[^>]+>/g, "\n"));
  }

  function classifyUrl(url) {
    const low = String(url || "").toLowerCase();
    if (BLOCKED.some((b) => low.includes(b))) return "blocked";
    if (low.includes("bing.com/spotlight/imagepuzzle")) return "puzzle";
    if (low.includes("homepage%20quiz") || low.includes("homepage+quiz") || low.includes("/earn/quest/")) return "manual";
    if (
      low.startsWith("https://www.bing.com/search") ||
      low.startsWith("https://cn.bing.com/search") ||
      low.startsWith("https://microsoftedgewelcome.microsoft.com/")
    ) {
      return "browse";
    }
    return "blocked";
  }

  function extractOffers(rawHtml) {
    const text = String(rawHtml || "").replace(/\\"/g, '"').replace(/\\u0026/g, "&");
    const out = [];
    const seen = new Set();
    const re = /\{[^{}]*"(?:destination|destinationUrl)"\s*:\s*"https:\/\/[^"]+"[^{}]*\}/g;
    let m;
    while ((m = re.exec(text)) !== null) {
      const chunk = m[0];
      if (!chunk.includes('"points"') || !chunk.includes('"title"')) continue;
      let o;
      try {
        o = JSON.parse(chunk.replace(/"\$undefined"/g, "null"));
      } catch (_) {
        continue;
      }
      const url = decodeEntities(String(o.destination || o.destinationUrl || "").trim());
      const title = String(o.title || "").trim();
      const pts = Number(o.points || 0);
      if (!url || !title || !pts) continue;
      const offerId = String(o.offerId || o.name || url);
      const key = `${offerId}|${url}`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({
        offerId,
        title: title.slice(0, 44),
        points: Math.round(pts),
        url,
        completed: o.isCompleted === true,
        locked: o.isLocked === true && o.isUnlocked !== true,
      });
    }
    return out;
  }

  async function inspectAll() {
    const [d, e, f] = await Promise.all([
      gmFetchText("https://rewards.bing.com/dashboard"),
      gmFetchText("https://rewards.bing.com/earn"),
      gmFetchText("https://www.bing.com/rewardsapp/flyout?channel=bingflyout&partnerId=BingRewards"),
