    const dashText = stripTags(d.text);
    const earnText = stripTags(e.text);
    const flyText = stripTags(f.text);
    const earnUnesc = e.text.replace(/\\"/g, '"');

    let avail = null;
    for (const [re, s] of [[/"availablePoints"\s*:\s*(\d+)/, earnUnesc], [/可用积分\s*([\d,]+)/, dashText], [/可用积分\s*([\d,]+)/, earnText]]) {
      const m = s.match(re);
