      const m = s.match(re);
      if (m) { searchEarned = parseInt(m[1], 10); searchMax = parseInt(m[2], 10); break; }
    }

    const daily = [];
    const seen = new Set();
    for (const o of extractOffers(d.text)) {
      const low = o.url.toLowerCase();
      if (!low.includes("dailyset") && !low.includes("rnoreward=1") && !o.offerId.toLowerCase().includes("dailyset")) continue;
