      if (seen.has(o.url) || o.url.toLowerCase().includes("dailyset")) continue;
      const kind = classifyUrl(o.url);
      if (kind === "blocked" || kind === "manual") continue;
      seen.add(o.url);
      earnCards.push({ id: `earn:${o.offerId}`, category: kind === "puzzle" ? "拼图(自动跳过)" : "日常浏览", kind, ...o });
    }

    return { ok: true, avail, todayPts, searchEarned, searchMax, daily, earnCards };
  }

