        <div class="msg-box">
          <div id="mh" class="msg-h">极其猫准备就绪啦</div>
          <div id="md" class="msg-d">点「开始运行」自动完成今日打卡、日常浏览、拼图跳过与低频拟人搜索。</div>
          <div id="cd" class="cd" style="display:none;"></div>
        </div>
        <div class="stats">
          <div class="st"><div class="st-l">可用积分</div><div id="vAvail" class="st-v" style="color:#fbbf24;">--</div></div>
          <div class="st"><div class="st-l">日常与打卡</div><div id="vCards" class="st-v" style="color:#34d399;">0/0</div></div>
          <div class="st"><div class="st-l">必应搜索</div><div id="vSearch" class="st-v" style="color:#38bdf8;">0/60</div></div>
        </div>
        <div class="bar"><div id="barIn" class="bar-in"></div></div>
        <div class="seg" id="seg">
          <button data-k="steady">稳健老号</button>
          <button data-k="new_account">新号养号</button>
          <button data-k="activities_only">仅打卡</button>
        </div>
        <div class="row">
          <button id="btnStart" class="btn btn-p">开始运行</button>
          <button id="btnSkip" class="btn btn-s">跳过等待</button>
          <button id="btnStop" class="btn btn-d">停止</button>
        </div>
      </div>
    </div>
  `;

  const $s = (id) => shadow.getElementById(id);
  let cfg = loadCfg();
  let running = false;
  let stopFlag = false;
  let skipFlag = false;

  function setMsg(h, d, cd = "") {
    $s("mh").textContent = h;
    $s("md").textContent = d;
    if (cd) {
      $s("cd").style.display = "block";
      $s("cd").textContent = cd;
    } else {
      $s("cd").style.display = "none";
    }
  }

  function applyCollapse() {
    $s("card").classList.toggle("hide", Boolean(cfg.collapsed));
    $s("fab").classList.toggle("show", Boolean(cfg.collapsed));
  }

  function applyProfileBtns() {
    shadow.querySelectorAll("#seg button").forEach((b) => {
      b.classList.toggle("active", b.dataset.k === cfg.profileKey);
    });
  }

  async function waitSec(sec, title, desc) {
    skipFlag = false;
    for (let r = Math.max(1, Math.round(sec)); r > 0; r--) {
      if (stopFlag) return false;
      if (skipFlag) { skipFlag = false; break; }
      const mm = String(Math.floor(r / 60)).padStart(2, "0");
      const ss = String(r % 60).padStart(2, "0");
      setMsg(title, desc, `⏳ 还剩 ${mm}:${ss}`);
      await sleep(1000);
    }
    setMsg(title, desc, "");
    return !stopFlag;
  }

  async function startRun() {
    if (running) return;
    running = true;
    stopFlag = false;
    const prof = PROFILES[cfg.profileKey] || PROFILES.steady;
    const hist = loadHist();
    const rec = getTodayRec(hist);

    try {
      setMsg("正在扫描今日全部积分任务...", "免跨域读取 Rewards 打卡、日常浏览、拼图与搜索进度...");
      const info = await inspectAll();
      if (!info.ok) {
        setMsg("需要处理", info.alert || "读取页面失败");
        return;
      }
      if (info.avail !== null) $s("vAvail").textContent = info.avail.toLocaleString();
      const targetSearch = prof.enableSearch ? Math.min(prof.maxSearchPoints, info.searchMax || 60) : 0;
      let curSearch = info.searchEarned || 0;
      $s("vSearch").textContent = `${curSearch}/${targetSearch}`;

      const allCards = [...(prof.enableDaily ? info.daily : []), ...(prof.enableEarn ? info.earnCards : [])];
      const pending = allCards.filter((c) => !c.completed && !c.locked && !rec.doneIds.includes(c.id));
      let doneCount = allCards.length - pending.length;
      const updateCardUI = () => {
        $s("vCards").textContent = `${doneCount}/${allCards.length}`;
        const pct = allCards.length ? Math.round((doneCount / allCards.length) * 100) : 100;
        $s("barIn").style.width = `${pct}%`;
      };
      updateCardUI();

      for (let i = 0; i < pending.length; i++) {
        if (stopFlag) return;
        const c = pending[i];
        const isPuzzle = c.kind === "puzzle";
        setMsg(
          `${isPuzzle ? "拼图自动跳过" : "浏览任务"} (${i + 1}/${pending.length})`,
          `后台打开「${c.title}」(+${c.points} 分)...`
        );
        await openBgTabAndDwell(c.url, isPuzzle ? 11000 : randInt(10000, 15000), isPuzzle);
        if (!rec.doneIds.includes(c.id)) rec.doneIds.push(c.id);
        saveHist(hist);
        doneCount += 1;
        updateCardUI();
        if (i + 1 < pending.length) {
          if (!(await waitSec(randInt(prof.cardGapMin, prof.cardGapMax), "防风控小憩片刻～", `准备做下一个任务 (${i + 2}/${pending.length})`))) return;
        }
      }

      if (prof.enableSearch && curSearch < targetSearch) {
        const recent = new Set(hist.queries || []);
        const pool = [...NATURAL_QUERIES].sort(() => Math.random() - 0.5);
        let batchLimit = randInt(prof.batchMin, prof.batchMax);
        let batchDone = 0;
        let lastAvail = info.avail || 0;
        let noGain = 0;

        for (let step = 1; curSearch < targetSearch && step <= 32 && !stopFlag; step++) {
          const q = pool.find((x) => !recent.has(x)) || `生活常识推荐 ${step}`;
          recent.add(q);
          hist.queries.push(q);
          saveHist(hist);

          setMsg(`模拟真人必应搜索 (${curSearch}/${targetSearch} 分)`, `第 ${step} 次：搜索「${q}」...`);
          await openBgTabAndDwell(`https://www.bing.com/search?q=${encodeURIComponent(q)}&FORM=QBLH`, randInt(11000, 16000));
          batchDone += 1;

          if (step % 2 === 0 || batchDone >= batchLimit) {
            const v = await inspectAll();
            if (v.ok) {
              if (v.avail !== null) $s("vAvail").textContent = v.avail.toLocaleString();
              const delta = v.avail && lastAvail ? Math.max(0, v.avail - lastAvail) : 0;
              if (delta > 0) {
                lastAvail = v.avail;
                curSearch = Math.min(targetSearch, Math.max(curSearch + delta, v.searchEarned || 0));
                noGain = 0;
              } else if ((v.searchEarned || 0) > curSearch) {
                curSearch = v.searchEarned;
                noGain = 0;
              } else {
                noGain += 1;
              }
              $s("vSearch").textContent = `${curSearch}/${targetSearch}`;
              $s("barIn").style.width = `${Math.min(100, Math.round((curSearch / Math.max(1, targetSearch)) * 100))}%`;
            }
            if (curSearch >= targetSearch) break;
            if (noGain >= 2) {
              noGain = 0;
              batchDone = 0;
              if (!(await waitSec(prof.cooldownWait, "防风控 · 避开 15 分钟冷却", "检测到搜索冷却，先休眠 16 分钟保护账号～"))) return;
              continue;
            }
          }

          if (batchDone >= batchLimit) {
            batchDone = 0;
            batchLimit = randInt(prof.batchMin, prof.batchMax);
            if (!(await waitSec(randInt(prof.batchRestMin, prof.batchRestMax), "防风控 · 分批自然休息", "歇几分钟后再继续下一批搜索～"))) return;
          } else {
            if (!(await waitSec(randInt(prof.minSearchGap, prof.maxSearchGap), `模拟真人节奏 (${curSearch}/${targetSearch} 分)`, `刚搜完「${q}」，随机停顿防风控～`))) return;
          }
        }
      }

      setMsg("今日任务全部完成啦！", "所有打卡、日常浏览、拼图跳过与搜索均已安全完成～");
      $s("barIn").style.width = "100%";
      try {
        GM_notification({ title: "极其猫微软积分助手", text: "今日微软积分（Microsoft Rewards）任务已全部完成！", timeout: 5000 });
      } catch (_) {}
    } finally {
      running = false;
    }
  }

  $s("btnMin").addEventListener("click", () => { cfg.collapsed = true; saveCfg(cfg); applyCollapse(); });
  $s("fab").addEventListener("click", () => { cfg.collapsed = false; saveCfg(cfg); applyCollapse(); });
  $s("btnStart").addEventListener("click", () => startRun());
  $s("btnSkip").addEventListener("click", () => { skipFlag = true; });
  $s("btnStop").addEventListener("click", () => { stopFlag = true; skipFlag = true; setMsg("已手动停止", "点「开始运行」可随时继续。"); });
  shadow.querySelectorAll("#seg button").forEach((b) => {
    b.addEventListener("click", () => {
      cfg.profileKey = b.dataset.k;
      saveCfg(cfg);
      applyProfileBtns();
      setMsg(`已切换为「${PROFILES[cfg.profileKey].name}」模式`, "下次开始运行时生效。");
    });
  });

  applyCollapse();
  applyProfileBtns();
})();

