// 独立兼容脚本，与 Landray / EKP 官方无关。
// 仅用于你拥有或获授权管理的系统。

// 安装后默认不生效：
//   @match 指向保留域名 inactive.invalid（不会解析），所以不会命中任何真实页面。
//
// 配置方法：
//   Tampermonkey → 本脚本 → 设置 → 包括/排除 → 用户匹配 → 添加...
//   表单模板提交：
//     https://your-ekp.example.com/km/review/km_review_template/*
//     https://your-ekp.example.com/sys/xform/*
//   流程设计器跨页签/跨域名复制粘贴：
//     https://your-ekp.example.com/sys/lbpm/flowchart/*
//     https://your-other-ekp.example.com/sys/lbpm/flowchart/*
//   保存后刷新目标页面。
//
// 跨域名复制粘贴要求生产、测试使用同一个 Tampermonkey 脚本实例
// （同一个脚本里加两条用户匹配），不要分别安装两个副本。
//
// 不要勾选“原始匹配”来放范围；原始匹配只是占位，保持原样即可。

(function () {
  'use strict';

  var pageWindow = (typeof unsafeWindow !== 'undefined') ? unsafeWindow : window;
  var pageDocument = pageWindow.document;
  var LOG_PREFIX = '[EKP Compat]';
  var SCRIPT_VERSION = '1.8.1';
  var FLOW_KEY = 'ekp.flow.clipboard.v2';

  function log() {
    try {
      console.log.apply(console, [LOG_PREFIX].concat([].slice.call(arguments)));
    } catch (e) {}
  }

  function clipSet(value) {
    try {
      if (typeof GM_setValue === 'function') {
        GM_setValue(FLOW_KEY, value);
        return true;
      }
    } catch (e) {
      log('GM 剪贴板写入失败，尝试 localStorage：', e && e.message);
    }
    try {
      pageWindow.localStorage.setItem(FLOW_KEY, value);
      return true;
    } catch (e) {
      log('localStorage 剪贴板写入失败：', e && e.message);
      return false;
    }
  }

  function clipGet() {
    try {
      if (typeof GM_getValue === 'function') {
        var value = GM_getValue(FLOW_KEY, null);
        if (value !== null && value !== undefined && value !== '') return value;
      }
    } catch (e) {
      log('GM 剪贴板读取失败，尝试 localStorage：', e && e.message);
    }
    try {
      var local = pageWindow.localStorage.getItem(FLOW_KEY);
      if (local !== null && local !== '') return local;
    } catch (e) {}
    return null;
  }

  // ============================================================
  // 流程设计器：跨页签/跨域名复制粘贴
  // EKP 在 Chrome 下把流程 XML 存到当前页面的 #clipboardData，
  // 两个页签、不同域名都不共享；这里用 Tampermonkey GM 存储做共享剪贴板。
  // ============================================================
  function patchFlowClipboard() {
    if (pageWindow.__ekpFlowClipboardPatched) return true;
    if (typeof pageWindow.Com_SaveData !== 'function' || typeof pageWindow.Com_LoadData !== 'function') return false;

    var origSave = pageWindow.Com_SaveData;
    var origLoad = pageWindow.Com_LoadData;

    pageWindow.Com_SaveData = function (dataString) {
      if (typeof dataString === 'string' && dataString.length) {
        clipSet(dataString);
      }
      return origSave.apply(this, arguments);
    };

    pageWindow.Com_LoadData = function () {
      var data = clipGet();
      if (data !== null && data !== '') return data;
      return origLoad.apply(this, arguments);
    };

    pageWindow.__ekpFlowClipboardPatched = true;
    pageWindow.__ekpFlowClipboard = { version: SCRIPT_VERSION };
    log('流程剪贴板已启用：跨页签/跨域名共享');
    return true;
  }

  if (!patchFlowClipboard()) {
    var flowTries = 0;
    var flowTimer = setInterval(function () {
      if (patchFlowClipboard() || ++flowTries >= 30) clearInterval(flowTimer);
    }, 100);
  }

  // ============================================================
  // 流程设计器：macOS Cmd+C / Cmd+V
  // EKP 只注册了 ctrl+shift+C/V，且只判断 ctrlKey；
  // macOS 的 Command 是 metaKey，所以这里补一层映射。
  // ============================================================
  function patchFlowShortcuts() {
    if (pageWindow.__ekpFlowShortcutsPatched) return true;
    var fc = pageWindow.FlowChartObject;
    if (!fc || !fc.Operation || !fc.Operation.Hotkey) return false;
    var ctrlKeys = fc.Operation.Hotkey.CtrlHotkeys;
    if (!ctrlKeys) return false;
    var copyOp = ctrlKeys[67]; // C
    var pasteOp = ctrlKeys[86]; // V
    if (!copyOp || !pasteOp || typeof copyOp.Run !== 'function' || typeof pasteOp.Run !== 'function') return false;

    pageDocument.addEventListener('keydown', function (e) {
      if (!e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return;
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
      var code = e.keyCode || e.which || 0;
      var op = code === 67 ? copyOp : code === 86 ? pasteOp : null;
      if (!op) return;
      e.preventDefault();
      e.stopPropagation();
      op.Run(op.Argument);
    }, true);

    pageWindow.__ekpFlowShortcutsPatched = true;
    pageWindow.__ekpFlowShortcuts = { version: SCRIPT_VERSION };
    log('macOS 流程快捷键已启用：Cmd+C / Cmd+V');
    return true;
  }

  if (!patchFlowShortcuts()) {
    var shortcutTries = 0;
    var shortcutTimer = setInterval(function () {
      if (patchFlowShortcuts() || ++shortcutTries >= 30) clearInterval(shortcutTimer);
    }, 100);
  }

  // ============================================================
  // 表单模板：提交前的 attachEvent 兼容 + 单弹窗版本选择
  // ============================================================
  var XFORM_FLAG = '__ekpXformCompatWrapped';
  var XFORM_IE_NOTICE = '自定义表单不支持非IE';

  function attachEventShim(name, fn) {
    var target = (this && this.addEventListener) ? this : pageWindow;
    return target.addEventListener(String(name).replace(/^on/, ''), fn, false);
  }

  function showVersionDialog(firstMessage) {
    if (pageWindow.__ekpVersionDialogOpen) return;
    pageWindow.__ekpVersionDialogOpen = true;

    var defaultNew = /新版本/.test(firstMessage) && !/原版本/.test(firstMessage);
    var mask = pageDocument.createElement('div');
    mask.id = 'ekp-version-dialog-mask';
    mask.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:2147483647;display:flex;align-items:center;justify-content:center;';

    var box = pageDocument.createElement('div');
    box.style.cssText = 'width:420px;max-width:calc(100vw - 40px);background:#fff;border-radius:6px;box-shadow:0 8px 30px rgba(0,0,0,.25);font:14px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif;color:#333;';

    var header = pageDocument.createElement('div');
    header.textContent = '保存方式';
    header.style.cssText = 'padding:16px 20px;border-bottom:1px solid #eee;font-size:16px;font-weight:600;';

    var body = pageDocument.createElement('div');
    body.style.cssText = 'padding:20px;';

    var desc = pageDocument.createElement('div');
    desc.textContent = '表单内容已修改，请选择保存方式。';
    desc.style.cssText = 'margin-bottom:12px;color:#555;';

    var hint = pageDocument.createElement('div');
    hint.textContent = defaultNew ? '系统建议保存为新版本。' : '系统建议保存为原版本。';
    hint.style.cssText = 'margin-bottom:14px;color:#999;font-size:12px;';

    var labelNew = pageDocument.createElement('label');
    labelNew.style.cssText = 'display:block;margin:8px 0;cursor:pointer;';
    var radioNew = pageDocument.createElement('input');
    radioNew.type = 'radio';
    radioNew.name = 'ekp-version-choice';
    radioNew.value = 'new';
    radioNew.checked = defaultNew;
    labelNew.appendChild(radioNew);
    labelNew.appendChild(pageDocument.createTextNode(' 保存为新版本'));

    var labelOld = pageDocument.createElement('label');
    labelOld.style.cssText = 'display:block;margin:8px 0;cursor:pointer;';
    var radioOld = pageDocument.createElement('input');
    radioOld.type = 'radio';
    radioOld.name = 'ekp-version-choice';
    radioOld.value = 'old';
    radioOld.checked = !defaultNew;
    labelOld.appendChild(radioOld);
    labelOld.appendChild(pageDocument.createTextNode(' 保存为原版本'));

    body.appendChild(desc);
    body.appendChild(hint);
    body.appendChild(labelNew);
    body.appendChild(labelOld);

    var footer = pageDocument.createElement('div');
    footer.style.cssText = 'padding:12px 20px;border-top:1px solid #eee;text-align:right;';

    var btnCancel = pageDocument.createElement('button');
    btnCancel.type = 'button';
    btnCancel.textContent = '取消';
    btnCancel.style.cssText = 'margin-right:8px;padding:6px 18px;border:1px solid #ccc;background:#fff;border-radius:4px;cursor:pointer;';

    var btnSave = pageDocument.createElement('button');
    btnSave.type = 'button';
    btnSave.textContent = '保存';
    btnSave.style.cssText = 'padding:6px 18px;border:1px solid #2f7cf6;background:#2f7cf6;color:#fff;border-radius:4px;cursor:pointer;';

    footer.appendChild(btnCancel);
    footer.appendChild(btnSave);
    box.appendChild(header);
    box.appendChild(body);
    box.appendChild(footer);
    mask.appendChild(box);

    function cleanup() {
      if (mask.parentNode) mask.parentNode.removeChild(mask);
      pageWindow.__ekpVersionDialogOpen = false;
      pageDocument.removeEventListener('keydown', onKey, true);
    }
    function cancel() {
      cleanup();
    }
    function save() {
      var choice = radioNew.checked ? 'new' : 'old';
      cleanup();
      pageWindow.__ekpVersionChoice = choice;
      if (typeof pageWindow.submitForm === 'function') {
        pageWindow.submitForm('update');
      } else {
        var btn = pageDocument.getElementById('languageUpdate');
        if (btn) btn.click();
      }
    }
    function onKey(e) {
      if (e.key === 'Escape') {
        e.preventDefault();
        cancel();
      } else if (e.key === 'Enter') {
        e.preventDefault();
        save();
      }
    }

    btnCancel.addEventListener('click', cancel);
    btnSave.addEventListener('click', save);
    pageDocument.addEventListener('keydown', onKey, true);
    pageDocument.body.appendChild(mask);
    btnSave.focus();
  }

  function installXFormWrapper() {
    if (pageWindow[XFORM_FLAG]) return true;

    var orig = pageWindow.XForm_ConfirmFormChangedFun;
    if (typeof orig !== 'function') return false;

    var source = Function.prototype.toString.call(orig);
    if (source.indexOf('attachEvent') === -1) {
      pageWindow[XFORM_FLAG] = true;
      log('当前页面没有表单提交 attachEvent 硬校验，跳过');
      return true;
    }

    function callOriginal(confirmFn, thisArg, args) {
      var had = Object.prototype.hasOwnProperty.call(pageWindow, 'attachEvent');
      var prev = pageWindow.attachEvent;
      var prevConfirm = pageWindow.confirm;

      if (!had) pageWindow.attachEvent = attachEventShim;
      pageWindow.confirm = confirmFn;
      try {
        return orig.apply(thisArg, args);
      } finally {
        pageWindow.confirm = prevConfirm;
        if (!had) {
          try {
            delete pageWindow.attachEvent;
          } catch (e) {
            pageWindow.attachEvent = prev;
          }
        }
      }
    }

    var wrapped = function () {
      if (pageWindow.__ekpVersionDialogOpen) return false;

      // 用户已经在单弹窗里选过，第二次进入时按选择回答原来的两次 confirm
      if (pageWindow.__ekpVersionChoice) {
        var choice = pageWindow.__ekpVersionChoice;
        pageWindow.__ekpVersionChoice = null;
        return callOriginal(function (msg) {
          var isNew = /新版本/.test(msg) && !/原版本/.test(msg);
          var isOld = /原版本/.test(msg);
          if (isNew) return choice === 'new';
          if (isOld) return choice === 'old';
          return false;
        }, this, arguments);
      }

      // 第一遍：不弹原生 confirm，只捕获是否需要版本选择
      var prompts = [];
      var result = callOriginal(function (msg) {
        prompts.push(msg);
        return false;
      }, this, arguments);

      if (!prompts.length) return result;

      // 需要版本选择：只弹一个弹窗，然后中止本次提交；选完后再提交
      showVersionDialog(prompts[0]);
      return false;
    };

    wrapped.__ekpXformCompat = true;
    pageWindow.XForm_ConfirmFormChangedFun = wrapped;
    pageWindow[XFORM_FLAG] = true;
    pageWindow.__ekpXformCompat = { version: SCRIPT_VERSION };
    log('表单模板提交兼容已启用（单弹窗版本选择）');
    return true;
  }

  function patchXFormDesignerNotice() {
    var loadForm = pageWindow.LoadXForm;
    if (typeof loadForm !== 'function') return false;
    if (loadForm.__ekpXformNoticePatched) return true;
    if (Function.prototype.toString.call(loadForm).indexOf(XFORM_IE_NOTICE) === -1) return false;

    // EKP 发出提示后仍会加载设计器。每次打开时只过滤这条提示。
    var wrapped = function () {
      var notify = pageWindow.jNotify;
      if (typeof notify !== 'function') return loadForm.apply(this, arguments);

      function filterNotice(message) {
        if (typeof message === 'string' && message.indexOf(XFORM_IE_NOTICE) !== -1) return;
        return notify.apply(this, arguments);
      }

      pageWindow.jNotify = filterNotice;
      try {
        return loadForm.apply(this, arguments);
      } finally {
        if (pageWindow.jNotify === filterNotice) pageWindow.jNotify = notify;
      }
    };
    wrapped.__ekpXformNoticePatched = true;
    pageWindow.LoadXForm = wrapped;
    return true;
  }

  function startToastSuppression() {
    function dropTip(root) {
      if (!root || root.nodeType !== 1) return;
      if (root.id === 'jNotify' && (root.textContent || '').indexOf(XFORM_IE_NOTICE) >= 0) {
        root.parentNode && root.parentNode.removeChild(root);
        return;
      }
      if (root.querySelectorAll) {
        var list = root.querySelectorAll('#jNotify');
        for (var i = 0; i < list.length; i++) {
          if ((list[i].textContent || '').indexOf(XFORM_IE_NOTICE) >= 0) {
            list[i].parentNode && list[i].parentNode.removeChild(list[i]);
          }
        }
      }
    }

    dropTip(pageDocument.documentElement);
    if (patchXFormDesignerNotice()) return;

    var Observer = pageWindow.MutationObserver;
    if (Observer) {
      var observer = new Observer(function (mutations) {
        for (var i = 0; i < mutations.length; i++) {
          var added = mutations[i].addedNodes;
          for (var j = 0; j < added.length; j++) dropTip(added[j]);
        }
      });
      observer.observe(pageDocument.documentElement, { childList: true, subtree: true });
      setTimeout(function () { observer.disconnect(); }, 60000);
    }
  }

  function activateXForm() {
    if (installXFormWrapper()) {
      startToastSuppression();
      return true;
    }
    return false;
  }

  if (!activateXForm()) {
    var xformTries = 0;
    var xformTimer = setInterval(function () {
      if (activateXForm() || ++xformTries >= 20) clearInterval(xformTimer);
    }, 100);
  }
})();

