const playerProbe = `
setTimeout(function () {
  var r = { at: Date.now() };
  // 复刻「弹窗已经在页面上」：渲染一个平台样式的提示层，
  // 等脚本的 1 秒定时器跑一轮，它必须被自动收掉（真实场景是加载期失焦先弹出来）。
  if (typeof window.__renderLeavePopup === 'function') window.__renderLeavePopup();
  r.popupRendered = !!document.getElementById('leavePopup');
  // 不直接调用：必须由脚本自己的定时器收掉，才算接线正确
  r.onblurIsNull = (window.onblur === null);
  r.before = window.__blurCalls;
  window.dispatchEvent(new Event('blur'));
  r.afterDispatch = window.__blurCalls;
  var late = 0;
  window.addEventListener('blur', function () { late += 1; });
  window.dispatchEvent(new Event('blur'));
  r.lateFired = late;
  var host = document.getElementById('csta-panel-host');
  r.panel = !!(host && host.shadowRoot);
  if (r.panel) {
    var el = host.shadowRoot.querySelector('#fx-gb-play');
    r.playCnt = el ? el.textContent : null;
    var st = host.shadowRoot.querySelector('#fx-status');
    r.state = st ? st.textContent : null;
  }
  // 验证拦截器本身是否生效：用一个独立注册的 blur 监听当探针。
  // 平台的 onblur 在安装时已被摘掉，所以不能拿它当判据。
  var probeHits = 0;
  window.addEventListener('blur', function () { probeHits += 1; });
  var sr2 = host && host.shadowRoot;
  var tg = sr2 && sr2.querySelector('#fx-unlock');
  if (tg) {
    // 开关默认是「开」：拦截器应吃掉这次 blur，探针收不到
    probeHits = 0;
    window.dispatchEvent(new Event('blur'));
    r.probeOnBlocked = (probeHits === 0);

    // 关掉开关之前先取快照：关闭后平台会恢复正常弹窗/暂停，那是预期行为，
    // 不能混进「ON 阶段应当零弹窗」的统计里
    r.leaveAlertOn = (window.__alerts || []).filter(function (m) {
      return String(m).indexOf('视频将停止播放计时') >= 0;
    }).length;
    r.pausedOn = (window.__paused || []).slice();


    // 关掉开关后不再拦截，探针应收到
    tg.click();
    probeHits = 0;
    window.dispatchEvent(new Event('blur'));
    r.probeOffPassed = (probeHits === 1);

    // 再打开，恢复拦截
    tg.click();
    probeHits = 0;
    window.dispatchEvent(new Event('blur'));
    r.probeOnAgain = (probeHits === 0);
  }

  // 反复拨「意外暂停续播」不应累积 document 监听。
  // applyLive() 每次拨动都会重放 watchVideo()，而它里面挂 document click 监听 ——
  // 没有守卫时每拨一次「开启」就多挂一个，且没有上限（实测拨 6 次多 3 个）。
  r.clickListenersAdded = (function () {
    var before = window.__docClickCount || 0;
    var keep = sr2 && sr2.querySelector('#fx-keep');
    if (keep) { for (var i = 0; i < 6; i++) keep.click(); }
    return (window.__docClickCount || 0) - before;
  })();

  // 静音开关：默认开 → 脚本把 video 静音；关掉后必须把声音还回去。
  // install() 只在首次执行，所以这一步实际在验 applyLive() 有没有跑。
  var muteBtn = sr2 && sr2.querySelector('#fx-mute');
  var vid = document.querySelector('video');
  if (muteBtn && vid) {
    r.mutedDefault = vid.muted;          // 应为 true（fixture 带 muted 属性 + 脚本也设了）
    muteBtn.click();                     // 关掉静音
    r.mutedAfterOff = vid.muted;          // 应为 false
    muteBtn.click();                     // 再打开
    r.mutedAfterOn = vid.muted;           // 应为 true
  }

  // ---- 失焦三层防护（对应 v1.3.20）----
  // 平台真实行为：window.onblur → Showbo.Msg.alert(…停止播放计时…) + 2 秒后 myJwPlayer.play(false)
  r.leaveAlertShown = (window.__alerts || []).filter(function (m) {
    return String(m).indexOf('视频将停止播放计时') >= 0;
  }).length;
  // 主动触发一条「非失焦」提示，验证拦截器只认那条文案、不误伤别的
  if (window.Showbo) Showbo.Msg.alert('毕业条件如下: 1、必修课…');
  r.otherAlertShown = (window.__alerts || []).filter(function (m) {
    return String(m).indexOf('毕业条件') >= 0;
  }).length;
  r.pausedWithinWindow = (window.__paused || []).slice();

  // ---- 最坏情况：事件层完全失效 ----
  // 真实 Edge 上的表现就是如此（日志出现「意外暂停」说明 isLeaveOrEnter 确实跑了）。
  // 直接调平台回调、绕开我们的 blur 拦截，验证结果层兜底独立生效。
  window.__alerts.length = 0;
  window.__paused.length = 0;
  if (typeof window.__isLeaveOrEnter === 'function') window.__isLeaveOrEnter();
  r.bypassAlertSuppressed = (window.__alerts.filter(function (m) {
    return String(m).indexOf('视频将停止播放计时') >= 0;
  }).length === 0);

  // 平台在 2 秒后调 myJwPlayer.play(false)，等它跑完再继续
  setTimeout(function () {
    r.pausedAfterBypass = (window.__paused || []).slice();
    // 顺手复查上面渲染的提示层是否已被定时器收掉（1 秒 tick 早就跑过了）
    r.popupLeftOnScreen = !!document.getElementById('leavePopup');
    r.bodyAlive = !!(document.body && document.getElementById('__r'));

    // ---- 续播行为 ----
    var v2 = document.querySelector('video');
    var finish = function () {
      r.errors = window.__pageErrors;
      document.getElementById('__r').textContent = JSON.stringify(r);
    };
    if (!v2) { r.resumeChecked = 'no-video'; finish(); return; }

    // ① 意外暂停（无手动痕迹）→ 应自动恢复。
    // 刻意把 document.hidden 强制为 true：真实场景就是「在后台标签页被平台暂停」，
    // 若哪天有人把「document.hidden 就不恢复」这个条件加回来，这条断言才会真的红。
    var oldHidden = Object.getOwnPropertyDescriptor(document, 'hidden');
    try {
      Object.defineProperty(document, 'hidden', { configurable: true, get: function () { return true; } });
    } catch (e) { /* 忽略 */ }
    v2.play().catch(function () {});
    setTimeout(function () {
      v2.pause();
      setTimeout(function () {
        r.autoResumed = (v2.paused === false);
        r.hiddenDuringTest = document.hidden;

        // ② 手动暂停（先点控制条留下手动痕迹）→ 不该被抢播
        v2.dispatchEvent(new MouseEvent('click', { bubbles: true }));
        if (v2.paused) { /* 已暂停就不用再 pause */ } else { v2.pause(); }
        setTimeout(function () {
          r.manualStayedPaused = (v2.paused === true);
          // 还原 document.hidden，免影响后续断言
          try {
            if (oldHidden) Object.defineProperty(document, 'hidden', oldHidden);
            else delete document.hidden;
          } catch (e) { /* 忽略 */ }
          finish();
        }, 900);
      }, 900);
    }, 200);
  }, 2300);
}, 2500);
`;

