 * - X / Twitter (x.com & twitter.com /<user>/status/<id>, /i/status/<id>, /video/1..4, t.co)
 * - Douyin (douyin.com /video/<id>, /share/video/<id>, ?modal_id=<id>, v.douyin.com)
 * - Xiaohongshu / RedNote (xiaohongshu.com, rednote.com, xhslink.com, xhslink.cn)
 */

function openInVidleaf(win) {
  var ENDPOINT = 'https://vidleaf.app/open?url=';
  var HOST_RE = /(^|\.)(youtube\.com|youtu\.be|youtube-nocookie\.com|bilibili\.com|bilibili\.tv|biliintl\.com|b23\.tv|bili\.im|bili2233\.cn|douyin\.com|iesdouyin\.com|xiaohongshu\.com|rednote\.com|xhslink\.com|xhslink\.cn|x\.com|twitter\.com|t\.co)$/i;
  var X_SKIP = /^(i|home|explore|search|notifications|messages|settings|compose|hashtag|tos|privacy|intent|share|safety|login|logout|signup)$/i;

  function extractSelectedUrl() {
    try {
      var sel = win.getSelection ? String(win.getSelection()).trim() : '';
      if (!sel) return '';
      var match = sel.match(/https?:\/\/[^\s"'<>]+/i);
      return match ? match[0].replace(/[.,;:!?)]+$/, '') : '';
    } catch (_) {
      return '';
    }
  }

  function resolvePageVideoUrl(loc) {
    var host = (loc.hostname || '').toLowerCase();
    if (!HOST_RE.test(host)) return '';

    var path = loc.pathname || '/';
    var params = new URLSearchParams(loc.search || '');
    var t = params.get('t');
    var tParam = t && /^[0-9hms.]+$/i.test(t) ? t : '';

    if (/(^|\.)(youtube\.com|youtube-nocookie\.com)$/i.test(host)) {
      var v = params.get('v');
      if (path === '/watch' && v) {
        return 'https://www.youtube.com/watch?v=' + encodeURIComponent(v) + (tParam ? '&t=' + encodeURIComponent(tParam) : '');
      }
      if (/^\/(shorts|live|embed)\/[A-Za-z0-9_-]{11}\/?$/.test(path)) {
        return 'https://www.youtube.com' + path.replace(/\/$/, '');
      }
      return '';
    }

    if (host === 'youtu.be') {
      var yid = path.replace(/^\/+|\/+$/g, '');
      return /^[A-Za-z0-9_-]{11}$/.test(yid)
        ? 'https://youtu.be/' + yid + (tParam ? '?t=' + encodeURIComponent(tParam) : '')
        : '';
    }

    if (/(^|\.)bilibili\.com$/i.test(host)) {
      if (/^\/(bangumi\/play\/(ep|ss)|cheese\/play\/ep)[1-9]\d*\/?$/i.test(path)) {
        return 'https://www.bilibili.com' + path.replace(/\/$/, '');
      }
      var bvMatch = path.match(/^\/video\/(BV[A-Za-z0-9]{10}|av\d+)/i);
      var bvid = bvMatch ? bvMatch[1] : (/^\/(festival|list|medialist|blackboard)\//i.test(path) && /^BV[A-Za-z0-9]{10}$/.test(params.get('bvid') || '') ? params.get('bvid') : '');
      if (bvid) {
        var ep = params.get('p');
        var qParts = [];
        if (ep && ep !== '1' && /^\d+$/.test(ep)) qParts.push('p=' + encodeURIComponent(ep));
        if (tParam) qParts.push('t=' + encodeURIComponent(tParam));
        return 'https://www.bilibili.com/video/' + bvid + (qParts.length ? '?' + qParts.join('&') : '');
      }
      return '';
    }

    if (/(^|\.)(bilibili\.tv|biliintl\.com)$/i.test(host)) {
      var intl = path.match(/\/video\/([1-9]\d{0,19})\/?$/);
      return intl ? 'https://www.bilibili.tv/en/video/' + intl[1] : '';
    }

    if (/(^|\.)(douyin\.com|iesdouyin\.com)$/i.test(host)) {
      var modalId = params.get('modal_id');
      if (modalId && /^\d+$/.test(modalId)) return 'https://www.douyin.com/video/' + modalId;
      var dy = path.match(/^\/(?:share\/)?video\/(\d+)/);
      return dy ? 'https://www.douyin.com/video/' + dy[1] : '';
    }

    if (/(^|\.)(xiaohongshu|rednote)\.com$/i.test(host)) {
      return /^\/(explore|discovery\/item)\/[0-9a-fA-F]{24}\/?$/.test(path) ? loc.href : '';
    }

    if (/(^|\.)(x|twitter)\.com$/i.test(host)) {
      var xm = path.match(/^\/(?:i(?:\/web)?\/status|statuses|([A-Za-z0-9_]{1,15})\/status(?:es)?)\/([1-9]\d{0,19})(?:\/(video|photo)\/([^/]*))?\/?$/i);
      if (!xm || (xm[1] && X_SKIP.test(xm[1])) || xm[3] === 'photo') return '';
      if (xm[3] === 'video' && !/^[1-4]$/.test(xm[4] || '')) return '';
      var vIdx = xm[3] === 'video' && xm[4] !== '1' ? '/video/' + xm[4] : '';
      return 'https://x.com/i/status/' + xm[2] + vIdx;
    }

    return loc.href;
  }

  var targetUrl = extractSelectedUrl() || resolvePageVideoUrl(win.location);
  if (!targetUrl) {
    var input = win.prompt('Open in Vidleaf — paste a YouTube, Bilibili, X (Twitter), Douyin, or Xiaohongshu video URL:');
    if (!input || !input.trim()) return null;
    targetUrl = input.trim();
  }

  var destination = ENDPOINT + encodeURIComponent(targetUrl);
  var popup = win.open(destination, '_blank', 'noopener,noreferrer');
  if (!popup) {
    win.location.href = destination;
  }
  return destination;
}

