(function () {
  'use strict';

  var VIDLEAF_OPEN_ENDPOINT = 'https://vidleaf.app/open?url=';
  var BTN_ID = 'vidleaf-quick-open-btn';
  var FLOAT_ID = 'vidleaf-quick-open-float';
  var STYLE_ID = 'vidleaf-quick-open-style';
  var X_SKIP_HANDLES = /^(i|home|explore|search|notifications|messages|settings|compose|hashtag|tos|privacy|intent|share|safety|login|logout|signup)$/i;

  var navLang = ((typeof navigator !== 'undefined' && navigator.language) || 'en').toLowerCase();
  var locale = /^zh-(hant|tw|hk|mo)/.test(navLang)
    ? 'zh-Hant'
    : /^zh\b/.test(navLang)
      ? 'zh-CN'
      : /^ja\b/.test(navLang)
        ? 'ja'
        : /^pt\b/.test(navLang)
          ? 'pt-BR'
          : 'en';

  var COPY = {
    'zh-CN': {
      label: '在 Vidleaf 读字幕',
      tooltip: '免登录提取字幕、搜原话并导出 SRT/TXT/Markdown (Alt+V)',
      hide: '本次会话隐藏'
    },
    'zh-Hant': {
      label: '在 Vidleaf 讀字幕',
      tooltip: '免登入擷取字幕、搜尋原話並匯出 SRT/TXT/Markdown (Alt+V)',
      hide: '本次工作階段隱藏'
    },
    ja: {
      label: 'Vidleaf で字幕を読む',
      tooltip: 'ログインなしで字幕検索・SRT/TXT/Markdown出力 (Alt+V)',
      hide: 'このタブで非表示'
