      label: 'Open in Vidleaf',
      tooltip: 'Read, search & export captions as SRT/TXT/Markdown in Vidleaf (Alt+V)',
      hide: 'Hide for this tab'
    }
  };
  var LABEL_TEXT = COPY[locale].label;
  var TOOLTIP_TEXT = COPY[locale].tooltip;
  var HIDE_TEXT = COPY[locale].hide;

  var dismissedForSession = false;

  /**
   * Normalizes a supported video page URL. Returns empty string on non-video pages
   * (such as home feeds, photo posts, or search result listings) so no button is shown unnecessarily.
   */
  function resolveVideoUrl(loc) {
    var host = (loc.hostname || '').toLowerCase();
    var path = loc.pathname || '/';
    var params = new URLSearchParams(loc.search || '');
    var t = params.get('t');
    var tParam = t && /^[0-9hms.]+$/i.test(t) ? t : '';

    if (/(^|\.)youtube\.com$/i.test(host)) {
      var v = params.get('v');
      if (path === '/watch' && v) {
        return 'https://www.youtube.com/watch?v=' + encodeURIComponent(v) + (tParam ? '&t=' + encodeURIComponent(tParam) : '');
      }
      if (/^\/(shorts|live|embed)\/[A-Za-z0-9_-]{11}\/?$/.test(path)) {
        return 'https://www.youtube.com' + path.replace(/\/$/, '');
      }
      return '';
    }

    if (/(^|\.)bilibili\.com$/i.test(host)) {
      if (/^\/(bangumi\/play\/(ep|ss)|cheese\/play\/ep)[1-9]\d*\/?$/i.test(path)) {
        return 'https://www.bilibili.com' + path.replace(/\/$/, '');
      }
      var bvMatch = path.match(/^\/video\/(BV[A-Za-z0-9]{10}|av\d+)/i);
      var bvid = bvMatch
        ? bvMatch[1]
        : (/^\/(festival|list|medialist|blackboard)\//i.test(path) && /^BV[A-Za-z0-9]{10}$/.test(params.get('bvid') || '')
          ? params.get('bvid')
          : '');
      if (bvid) {
        var ep = params.get('p');
        var qParts = [];
        if (ep && ep !== '1' && /^\d+$/.test(ep)) qParts.push('p=' + encodeURIComponent(ep));
        if (tParam) qParts.push('t=' + encodeURIComponent(tParam));
        return 'https://www.bilibili.com/video/' + bvid + (qParts.length ? '?' + qParts.join('&') : '');
      }
      return '';
    }

    if (/(^|\.)bilibili\.tv$/i.test(host)) {
      var intl = path.match(/\/video\/([1-9]\d{0,19})\/?$/);
      return intl ? 'https://www.bilibili.tv/en/video/' + intl[1] : '';
    }

    if (/(^|\.)douyin\.com$/i.test(host)) {
      var modalId = params.get('modal_id');
      if (modalId && /^\d+$/.test(modalId)) {
        return 'https://www.douyin.com/video/' + modalId;
      }
      var dy = path.match(/^\/(?:share\/)?video\/(\d+)/);
      if (dy) {
        return 'https://www.douyin.com/video/' + dy[1];
      }
      return '';
    }

    if (/(^|\.)(xiaohongshu|rednote)\.com$/i.test(host)) {
      if (/^\/(explore|discovery\/item)\/[0-9a-fA-F]{24}\/?$/.test(path)) {
        return loc.href;
      }
      return '';
    }

    if (/(^|\.)(x|twitter)\.com$/i.test(host)) {
      var xm = path.match(/^\/(?:i(?:\/web)?\/status|statuses|([A-Za-z0-9_]{1,15})\/status(?:es)?)\/([1-9]\d{0,19})(?:\/(video|photo)\/([^/]*))?\/?$/i);
      if (!xm || (xm[1] && X_SKIP_HANDLES.test(xm[1])) || xm[3] === 'photo') return '';
      if (xm[3] === 'video' && !/^[1-4]$/.test(xm[4] || '')) return '';
      var vIdx = xm[3] === 'video' && xm[4] !== '1' ? '/video/' + xm[4] : '';
      return 'https://x.com/i/status/' + xm[2] + vIdx;
    }

    return '';
  }

  function buildVidleafHref(videoUrl) {
    return VIDLEAF_OPEN_ENDPOINT + encodeURIComponent(videoUrl);
  }

  function launchVidleaf(videoUrl) {
    if (!videoUrl) return;
    var target = buildVidleafHref(videoUrl);
    if (typeof GM_openInTab === 'function') {
      GM_openInTab(target, { active: true, insert: true });
      return;
    }
    var win = window.open(target, '_blank', 'noopener,noreferrer');
    if (!win) {
      window.location.href = target;
    }
  }

  function injectStyles() {
    if (document.getElementById(STYLE_ID)) return;
    var style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = [
      '#' + BTN_ID + ' {',
      '  display: inline-flex;',
      '  align-items: center;',
      '  gap: 6px;',
      '  height: 36px;',
      '  padding: 0 14px;',
      '  margin-left: 8px;',
      '  border-radius: 999px;',
      '  border: 1px solid rgba(127, 127, 127, 0.28);',
      '  background: rgba(255, 255, 255, 0.92);',
