      '  line-height: 1;',
      '  text-decoration: none;',
      '  cursor: pointer;',
      '  white-space: nowrap;',
      '  transition: background 0.15s ease, border-color 0.15s ease;',
      '}',
      'html[dark] #' + BTN_ID + ', [data-theme="dark"] #' + BTN_ID + ' {',
      '  background: rgba(255, 255, 255, 0.1);',
      '  border-color: rgba(255, 255, 255, 0.16);',
      '  color: #f1f5f9;',
      '}',
      '#' + BTN_ID + ':hover {',
      '  background: #e0f2fe;',
      '  border-color: #38bdf8;',
      '  color: #0369a1;',
      '}',
      'html[dark] #' + BTN_ID + ':hover {',
      '  background: rgba(56, 189, 248, 0.2);',
      '  border-color: #38bdf8;',
      '  color: #bae6fd;',
      '}',
      '#' + FLOAT_ID + ' {',
      '  position: fixed;',
      '  right: 20px;',
      '  bottom: 84px;',
      '  z-index: 2147483640;',
      '  display: inline-flex;',
      '  align-items: center;',
      '  gap: 4px;',
      '  padding: 4px 6px 4px 12px;',
      '  border-radius: 999px;',
      '  background: rgba(15, 23, 42, 0.88);',
      '  color: #f8fafc;',
      '  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.22);',
      '  backdrop-filter: blur(8px);',
      '  font-family: system-ui, -apple-system, sans-serif;',
      '  font-size: 13px;',
      '}',
      '#' + FLOAT_ID + ' a {',
      '  color: #f8fafc;',
      '  text-decoration: none;',
      '  font-weight: 500;',
      '  padding-right: 4px;',
      '}',
      '#' + FLOAT_ID + ' a:hover { color: #7dd3fc; }',
      '#' + FLOAT_ID + ' button {',
      '  border: none;',
      '  background: transparent;',
      '  color: #94a3b8;',
      '  cursor: pointer;',
      '  font-size: 14px;',
      '  line-height: 1;',
      '  padding: 2px 6px;',
      '  border-radius: 999px;',
      '}',
      '#' + FLOAT_ID + ' button:hover { color: #ffffff; background: rgba(255,255,255,0.14); }'
    ].join('\n');
    (document.head || document.documentElement).appendChild(style);
  }

  function createSvgIcon() {
    var svgNS = 'http://www.w3.org/2000/svg';
    var svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('width', '14');
    svg.setAttribute('height', '14');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('fill', 'none');
    svg.setAttribute('stroke', 'currentColor');
    svg.setAttribute('stroke-width', '2');
    svg.setAttribute('stroke-linecap', 'round');
    svg.setAttribute('stroke-linejoin', 'round');
    var p1 = document.createElementNS(svgNS, 'path');
    p1.setAttribute('d', 'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z');
    var p2 = document.createElementNS(svgNS, 'polyline');
    p2.setAttribute('points', '14 2 14 8 20 8');
    var p3 = document.createElementNS(svgNS, 'line');
    p3.setAttribute('x1', '8');
    p3.setAttribute('y1', '13');
    p3.setAttribute('x2', '16');
    p3.setAttribute('y2', '13');
    var p4 = document.createElementNS(svgNS, 'line');
    p4.setAttribute('x1', '8');
    p4.setAttribute('y1', '17');
    p4.setAttribute('x2', '13');
    p4.setAttribute('y2', '17');
    svg.appendChild(p1);
    svg.appendChild(p2);
    svg.appendChild(p3);
    svg.appendChild(p4);
    return svg;
  }

  function removeWidgets() {
    var inlineBtn = document.getElementById(BTN_ID);
    if (inlineBtn && inlineBtn.parentNode) inlineBtn.parentNode.removeChild(inlineBtn);
    var floatPill = document.getElementById(FLOAT_ID);
    if (floatPill && floatPill.parentNode) floatPill.parentNode.removeChild(floatPill);
  }

  function findInlineMountTarget() {
    var host = (window.location.hostname || '').toLowerCase();
    var path = window.location.pathname || '/';
    if (/(^|\.)youtube\.com$/i.test(host) && host !== 'music.youtube.com' && path === '/watch') {
      return (
        document.querySelector('ytd-watch-metadata #top-level-buttons-computed') ||
        document.querySelector('#above-the-fold #top-level-buttons-computed')
      );
    }
    if (/(^|\.)bilibili\.com$/i.test(host) && /^\/(video|bangumi\/play|cheese\/play|list|festival|medialist)\//i.test(path)) {
      return (
        document.querySelector('.video-toolbar-left') ||
        document.querySelector('#arc_toolbar_report .video-toolbar-left-main') ||
        document.querySelector('#toolbar_module .toolbar-left')
      );
    }
    return null;
  }

  function syncUi() {
    if (typeof document === 'undefined' || !document.body) return;
    var videoUrl = resolveVideoUrl(window.location);
    if (!videoUrl) {
      removeWidgets();
      return;
    }

    injectStyles();
    var targetHref = buildVidleafHref(videoUrl);
    var inlineContainer = findInlineMountTarget();

    if (inlineContainer) {
      var floatExisting = document.getElementById(FLOAT_ID);
      if (floatExisting && floatExisting.parentNode) floatExisting.parentNode.removeChild(floatExisting);

      var btn = document.getElementById(BTN_ID);
      if (!btn) {
        btn = document.createElement('a');
        btn.id = BTN_ID;
        btn.target = '_blank';
        btn.rel = 'noopener noreferrer';
        btn.title = TOOLTIP_TEXT;
        btn.appendChild(createSvgIcon());
        var span = document.createElement('span');
        span.textContent = LABEL_TEXT;
        btn.appendChild(span);
        inlineContainer.appendChild(btn);
      }
      btn.href = targetHref;
      return;
    }

    // Fallback floating pill for YouTube Shorts, X (Twitter), Douyin, Xiaohongshu, or delayed toolbar loads
    if (dismissedForSession) return;
    var pill = document.getElementById(FLOAT_ID);
    if (!pill) {
      pill = document.createElement('div');
      pill.id = FLOAT_ID;

      var link = document.createElement('a');
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.title = TOOLTIP_TEXT;
      link.textContent = LABEL_TEXT + ' ↗';

      var closeBtn = document.createElement('button');
      closeBtn.type = 'button';
      closeBtn.title = HIDE_TEXT;
      closeBtn.textContent = '×';
      closeBtn.addEventListener('click', function (ev) {
        ev.preventDefault();
        ev.stopPropagation();
        dismissedForSession = true;
        removeWidgets();
      });

      pill.appendChild(link);
      pill.appendChild(closeBtn);
      document.body.appendChild(pill);
    }
    var anchor = pill.querySelector('a');
    if (anchor) anchor.href = targetHref;
  }

  function isEditableTarget(el) {
    if (!el) return false;
    var tag = (el.tagName || '').toUpperCase();
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || Boolean(el.isContentEditable);
  }

  function initBrowserHooks() {
    if (typeof GM_registerMenuCommand === 'function') {
      GM_registerMenuCommand(LABEL_TEXT + ' (Alt+V)', function () {
        var url = resolveVideoUrl(window.location) || window.location.href;
        launchVidleaf(url);
      });
    }

    window.addEventListener('keydown', function (ev) {
      if (ev.altKey && !ev.ctrlKey && !ev.metaKey && !ev.shiftKey && ev.code === 'KeyV') {
        if (isEditableTarget(document.activeElement)) return;
        var videoUrl = resolveVideoUrl(window.location);
        if (videoUrl) {
          ev.preventDefault();
          launchVidleaf(videoUrl);
        }
      }
    });

    window.addEventListener('yt-navigate-finish', syncUi);
    window.addEventListener('popstate', syncUi);

    var lastHref = window.location.href;
    var syncTimer = null;
    var observer = new MutationObserver(function () {
      if (window.location.href !== lastHref) {
        lastHref = window.location.href;
        dismissedForSession = false;
      }
      if (syncTimer) return;
      syncTimer = setTimeout(function () {
        syncTimer = null;
        syncUi();
      }, 350);
    });

    observer.observe(document.documentElement, { childList: true, subtree: true });
    syncUi();
  }

  if (typeof window !== 'undefined' && typeof document !== 'undefined') {
    initBrowserHooks();
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { resolveVideoUrl: resolveVideoUrl, buildVidleafHref: buildVidleafHref };
  }
})();

// ==UserScript==
// @name         CleanIG
// @description  Hides Reels tab, Explore grid, and Suggested posts on Instagram. Search, DMs, stories, and reels-in-chat all still work.
// @match        *://*.instagram.com/*
// @run-at       document-end
// @version      1.1
// @author       Hala
// ==/UserScript==
// RCC source attribution
// Original file: https://github.com/whalatte/reelsblocker/blob/main/cleanig.user.js
// SPDX-License-Identifier: MIT
// MIT License
// 
// Copyright (c) 2026 Hala
// 
// Permission is hereby granted, free of charge, to any person obtaining a copy
// of this software and associated documentation files (the "Software"), to deal
// in the Software without restriction, including without limitation the rights
// to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
// copies of the Software, and to permit persons to whom the Software is
// furnished to do so, subject to the following conditions:
// 
// The above copyright notice and this permission notice shall be included in all
// copies or substantial portions of the Software.
// 
// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
// IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
// FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
// AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
// LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
// OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
// SOFTWARE.


(function () {
    'use strict';

    // -----------------------------------------------------------------
    // CSS: hide the Reels tab in the bottom nav bar. The Explore icon
    // is kept because Hala wants search to work, and search lives on
    // /explore/. We hide the explore GRID separately in JS below.
    // -----------------------------------------------------------------
    const css = `
        a[href="/reels/"],
        a[href^="/reels/"] {
            display: none !important;
            visibility: hidden !important;
            pointer-events: none !important;
        }

        /* When we've flagged a page as blocked, hide its main content. */
        body[data-cleanig-blocked="reels"] main {
            display: none !important;
        }

        /* Marker class we add to suggested posts so they stay hidden
           even if the DOM gets re-rendered. */
        .cleanig-hidden {
            display: none !important;
        }
    `;

    if (!document.getElementById('cleanig-style')) {
        const style = document.createElement('style');
        style.id = 'cleanig-style';
        style.textContent = css;
        document.head.appendChild(style);
    }

    // -----------------------------------------------------------------
    // Home feed: hide everything after "You're all caught up".
    // That marker is the ground truth — everything below it is
    // algorithmic suggestions.
    // -----------------------------------------------------------------
    function hideAfterCaughtUp() {
        // Only run on the home feed, not on profiles/search/etc.
        if (location.pathname !== '/' && location.pathname !== '') return;

        // Walk every element with short-ish text and look for the marker.
        const candidates = document.querySelectorAll('span, div, h1, h2, h3');
        let marker = null;
        for (const el of candidates) {
            const t = (el.textContent || '').trim().toLowerCase();
            if (t.length > 60) continue; // skip long captions
            if (
                t === "you're all caught up" ||
                t === 'you’re all caught up' || // curly apostrophe variant
                t.startsWith("you're all caught up") ||
                t.startsWith('you’re all caught up') ||
                t.startsWith("you're caught up") ||
                t.startsWith('you’re caught up')
            ) {
                marker = el;
                break;
            }
        }
        if (!marker) return;

        // Walk up to the article/section that contains the marker,
        // then hide every following sibling in the feed.
        let container = marker;
        while (
            container &&
            container.parentElement &&
            container.tagName !== 'ARTICLE' &&
            container.tagName !== 'SECTION'
        ) {
            container = container.parentElement;
            // Stop climbing if we hit the body — safety.
            if (container === document.body) return;
        }
        if (!container) return;

        let sibling = container.nextElementSibling;
        while (sibling) {
            sibling.classList.add('cleanig-hidden');
            sibling = sibling.nextElementSibling;
        }
    }

    // -----------------------------------------------------------------
    // Fallback: hide any post whose own content contains a "Suggested"
    // label, even if the caught-up marker is missing. We look at ALL
    // descendants of each <article>, not just headings, because
    // Instagram sometimes buries the label in a small span.
    // -----------------------------------------------------------------
    function hideSuggestedPosts() {
        const articles = document.querySelectorAll('article');
        for (const art of articles) {
            if (art.classList.contains('cleanig-hidden')) continue;

            // Check up to the first ~80 text nodes inside the article.
            // Any short label matching "Suggested..." triggers the hide.
            let count = 0;
            const walker = document.createTreeWalker(
                art,
                NodeFilter.SHOW_TEXT,
                null
            );
            let node;
            while ((node = walker.nextNode()) && count < 80) {
                count++;
                const t = (node.nodeValue || '').trim().toLowerCase();
                if (t.length === 0 || t.length > 40) continue;
                if (
                    t === 'suggested for you' ||
                    t === 'suggested post' ||
                    t === 'suggested posts' ||
                    t === 'suggested' ||
                    t.startsWith('suggested for you')
                ) {
                    art.classList.add('cleanig-hidden');
                    break;
                }
            }
        }
    }

    // -----------------------------------------------------------------
    // Explore page: hide the trending grid but leave the search bar
    // and search results working. Heuristic: find containers that look
    // like a grid of post thumbnails (many image-containing links as
    // direct children) and hide those specifically.
    // -----------------------------------------------------------------
    function hideExploreGrid() {
        if (!location.pathname.startsWith('/explore')) return;

        // Skip when the user is actively searching. Search URLs look
        // like /explore/search/... or /explore/tags/... etc.
        if (
            location.pathname.startsWith('/explore/search') ||
            location.pathname.startsWith('/explore/tags') ||
            location.pathname.startsWith('/explore/locations') ||
            location.pathname.startsWith('/explore/people')
        ) {
            return;
        }

        // Look for containers whose direct children are mostly links
        // wrapping images — that's a thumbnail grid.
        const containers = document.querySelectorAll('main div, main section');
        for (const c of containers) {
            if (c.classList.contains('cleanig-hidden')) continue;
            const kids = c.children;
            if (kids.length < 6) continue; // need a reasonably full grid

            let imageLinks = 0;
            for (const k of kids) {
                // A grid cell typically contains an <a> wrapping an <img>.
                if (k.querySelector && k.querySelector('a img, img')) {
                    imageLinks++;
                }
            }
            // If most kids are image-cells, this is the grid.
            if (imageLinks >= 6 && imageLinks / kids.length >= 0.7) {
                c.classList.add('cleanig-hidden');
            }
        }
    }

    // -----------------------------------------------------------------
    // Hard block: if you land on /reels/ directly, show a "this is off"
    // screen instead of letting the Reels viewer open.
    // -----------------------------------------------------------------
    function enforceReelsBlock() {
        if (location.pathname.startsWith('/reels')) {
            document.body.setAttribute('data-cleanig-blocked', 'reels');
            showBlockedMessage('Reels tab is off. Reels friends send in DMs still work.');
            return;
        }
        document.body.removeAttribute('data-cleanig-blocked');
        const banner = document.getElementById('cleanig-banner');
        if (banner) banner.remove();
    }

    function showBlockedMessage(msg) {
        if (document.getElementById('cleanig-banner')) return;
        const div = document.createElement('div');
        div.id = 'cleanig-banner';
        div.textContent = msg;
        div.style.cssText = `
            position: fixed; inset: 0; z-index: 99999;
            display: flex; align-items: center; justify-content: center;
            text-align: center; padding: 2rem;
            background: #fafafa; color: #262626;
            font: 500 17px/1.4 -apple-system, system-ui, sans-serif;
        `;
        document.body.appendChild(div);
    }

    // -----------------------------------------------------------------
    // Run the full sweep. Instagram is a single-page app so the DOM
    // keeps changing — we re-run on every mutation (debounced) and on
    // every SPA route change.
    // -----------------------------------------------------------------
    function sweep() {
        try {
            enforceReelsBlock();
            hideAfterCaughtUp();
            hideSuggestedPosts();
            hideExploreGrid();
        } catch (e) {
            // Never let an error here break the page.
        }
    }
    sweep();

    let mutationTimer = null;
    const observer = new MutationObserver(() => {
        if (mutationTimer) return;
        mutationTimer = setTimeout(() => {
            mutationTimer = null;
            sweep();
        }, 150);
    });
    observer.observe(document.documentElement, {
        childList: true,
        subtree: true,
    });

    const originalPushState = history.pushState;
    history.pushState = function () {
        const r = originalPushState.apply(this, arguments);
        setTimeout(sweep, 50);
        return r;
    };
    window.addEventListener('popstate', () => setTimeout(sweep, 50));
})();

