            t = setTimeout(() => { t = null; fn(...args); }, wait);
        };
        wrapped.cancel = () => { if (t !== null) { clearTimeout(t); t = null; } };
        return wrapped;
    }

    /** Leading-edge throttle with trailing flush. */
    function throttle(fn, wait = 150) {
        let last = 0, t = null, pending = null;
        const wrapped = (...args) => {
            const now = Date.now();
            if (now - last >= wait) {
                last = now;
                fn(...args);
            } else {
