       re-inserts to refresh recency, so eviction removes the
       least-recently-USED key; the name is kept for surface stability, the
       behavior is the more useful of the two and kernel-smoke pins the
       set-path) ───────────────────────────── */

    class FIFOCache {
        constructor(max = 512) {
            this.max = max;
            this.map = new Map();
        }
        get(key) {
